buildTechSnapshotBlock.source:
function buildTechSnapshotBlock(sym, snap, setupState) {
  const s = snap || {};
  if (s.pct20 == null && s.pct50 == null) return '';
  const fmt  = v => v != null ? (v >= 0 ? '+' : '') + v.toFixed(2) + '%' : '—';
  const fmtV = v => v != null ? v.toFixed(2) + 'x' : '—';
  const etfLabel = s.sectorEtf ? ' vs ' + s.sectorEtf + ': ' + fmt(s.rsSector) : '';
  const _ath = (typeof _athCache === 'object' && _athCache) ? _athCache[sym] : null; // B4 (Entry 34): memory cache; absent in harnesses
  const _athLine = (_ath && _ath.state === 'verified') ? `  All-time high (verified): ${_ath.athValue.toFixed(2)} ${_ath.currency} (${_ath.athDate})\n` : ''; // D-B4-2 = A: verified only, never the 1Y High, no distance
  return (
    `${sym} [setup: ${setupState} = ${_setupDisplay(setupState)}]\n` +
    `  MA20: ${s.sma20 != null ? '$' + s.sma20.toFixed(2) : '—'} (${fmt(s.pct20)})` +
      `   MA50: ${s.sma50 != null ? '$' + s.sma50.toFixed(2) : '—'} (${fmt(s.pct50)})\n` +
    `  MA150: ${s.sma150 != null ? '$' + s.sma150.toFixed(2) : '—'} (${fmt(s.pct150)})\n` +
    `  1Y High Dist: ${fmt(s.high1yDist)}   Volume vs 20D avg: ${fmtV(s.volRatio)}\n` +
    `  RS vs SPY (3M): ${fmt(s.rsSPY)}   RS vs QQQ (3M): ${fmt(s.rsQQQ)}${etfLabel}\n` + _athLine
  );
}

renderMainPanel.source:
function renderMainPanel(item) {
  const panel = document.getElementById('mainPanel');
  if (!panel) return;

  const score = _ptScoreNorm(item.sentiment_score); // null = missing (never 50, never 0)
  const sent  = item.sentiment==='positive'?'positive':item.sentiment==='negative'?'negative':'neutral';
  let chg   = typeof item._verifiedChangePct==='number' ? item._verifiedChangePct : null;
  let price = item._verifiedPrice ? `$${item._verifiedPrice.toFixed(2)}` : '—';
  const sum   = item.summary || '';
  const sl    = sum.toLowerCase();

  const getS = tag => {
    const m = sum.match(new RegExp(tag+':?\\s*(.+?)(?=KEY EVENT:|ROOT CAUSE:|PRICE CONTEXT:|BULL VS BEAR:|ACTIONABLE TAKE:|Rating:|$)','si'));
    return m ? m[1].trim().replace(/\n/g,' ').replace(/\s+/g,' ') : '';
  };
  const actionable = getS('ACTIONABLE TAKE');
  const keyEvent   = getS('KEY EVENT');

  const rM = sum.match(RATING_SUMMARY_RE);
  const pM = sum.match(/PT:\s*\$?([\d,.]+|consensus unavailable)/i);
  const rating = rM ? rM[1] : null; // R-5 (Entry 37): no silent "Neutral" fallback
  const pt     = pM&&pM[1]!=='consensus unavailable'?'$'+pM[1]:'—';
  const _pulseBand = score === null ? 'neutral-v' : score >= 65 ? 'pos' : score <= 40 ? 'neg' : 'neutral-v'; // R-5 (Entry 37, ruling A1): the Pulse score band colours the dial and the chip

  // Data-quality flag — gates all derived technical/RS/volume metrics
  const hasData    = hasVerifiedMarketData(item);
  const _mktFailed = _mktFailCache[item.ticker] === true; // display-only; never read by scoring

  // Setup grade — removed from header in Phase 2b; kept as dead vars to avoid refactor
  // of lower body panels that may still reference sc/sg (safe: not rendered in header)
  const hasCrit = (item.alerts||[]).some(a=>a.type==='critical');

  // Timeframe Alignment — deterministic map from technical_setup (Phase 6A-3)
  const _tfMap={extended_near_ath:['EXTENDED','warn'],healthy_uptrend_near_ath:['BULLISH','pos'],healthy_uptrend:['BULLISH','pos'],pullback_in_uptrend:['MIXED','warn'],support_test:['MIXED','warn'],breakdown_risk:['BEARISH','neg'],below_key_mas:['BEARISH','neg']};
  const _panelSnap  = _techSnapFor(item.ticker, _techPanelPrice(item)); // Entry 32: one snapshot for distances and Setup
  const _panelSetup = hasData ? classifyTechnicalSetup(_panelSnap) : 'unknown';
  const _fromScan   = hasData && _techPanelPrice(item) !== item._verifiedPrice; // Entry 32: displayed price differs from scan price
  const [phase,phCls]=_panelSetup==='unknown'?['—','neutral-v']:(_tfMap[_panelSetup]||['NEUTRAL','neutral-v']);

  // State values
  const _scoreSt  = _ptScoreStates(score); // missing -> explicit '—' states, never MODERATE / IN LINE
  const riskState = _scoreSt.riskState;
  const riskCls   = _scoreSt.riskCls;
  const cat       = (sl.includes('earnings beat')||sl.includes('upgrade')||sl.includes('hbm')||sl.includes('ai demand'))?'CATALYST PRESENT':
                    (sl.includes('downgrade')||sl.includes('earnings miss'))?'NEGATIVE EVENT':
                    (sl.includes('no verified')||sl.includes('limited catalyst'))?'NO CATALYST':'MONITORING';
  const catCls    = cat==='CATALYST PRESENT'?'pos':cat==='NEGATIVE EVENT'?'neg':cat==='NO CATALYST'?'warn':'neutral-v';
  const volChar   = sl.includes('elevated volume')||sl.includes('high volume')?'ACCUMULATION':sl.includes('light volume')?'DISTRIBUTION':'NEUTRAL';
  const volCls    = volChar==='ACCUMULATION'?'pos':volChar==='DISTRIBUTION'?'neg':'neutral-v';
  const volReg    = Math.abs(chg||0)>4?'ELEVATED':Math.abs(chg||0)>1.5?'NORMAL':'LOW';
  const chgStr    = chg!==null?(chg>=0?'+':'')+chg.toFixed(2)+'%':'—';
  const chgCls    = chg===null?'':chg>0?'pos':chg<0?'neg':'';

  // Watchlist metadata — must be declared before refreshTechPanel call
  const wlEntry   = findTicker(item.ticker);
  const dispName  = ((wlEntry && wlEntry.name) || item.company_name || '').trim();
  const dispExch  = (wlEntry && wlEntry.exchange)  || '';
  const dispSect  = (wlEntry && wlEntry.sector)    || '';
  const dispEtf   = (wlEntry && wlEntry.sectorEtf) || '';
  const metaParts = [dispExch, dispSect].filter(Boolean);
  if (dispEtf) metaParts.push('Benchmark: ' + dispEtf);
  const metaStr   = metaParts.length ? metaParts.join(' · ') : '';

  // Technical snapshot — read from cache (populated async by refreshTechPanel)
  const snap  = _panelSnap;
  const maCls = v => v === 'pos' ? 'pos' : v === 'warn' ? 'warn' : v === 'neg' ? 'neg' : 'neutral-v';

  // Helper: format a pct diff for display
  function fmtPct(val) {
    if (val === null || val === undefined) return '—';
    return (val >= 0 ? '+' : '') + val.toFixed(2) + '%';
  }

  // 7A-2: Position Context helpers — render-only, no scoring/action impact
  function fmtMoney(v) { return '$' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function fmtPnl(v)   { return (v >= 0 ? '+' : '') + v.toFixed(2) + '%'; }
  function derivePositionMode(p) {
    if (!p || p.hasPosition !== true) return { key:'fresh',      label:'Fresh entry',                         cls:'mode-fresh',      valCls:'muted' };
    if (p.pnlPercent === null || p.pnlPercent === undefined)
                                       return { key:'unknown',    label:'Position open / P/L not entered',     cls:'mode-unknown',    valCls:'muted' };
    const v = p.pnlPercent;
    if (v >=  25)                      return { key:'big-winner', label:'Big winner / Protect gains',          cls:'mode-big-winner', valCls:'pos'  };
    if (v >=   5)                      return { key:'profitable', label:'Profitable / Hold core',              cls:'mode-profitable', valCls:'pos'  };
    if (v  >  -5)                      return { key:'flat',       label:'Flat / Decision zone',                cls:'mode-flat',       valCls:'warn' };
                                       return { key:'loss',       label:'Losing position / Risk control',      cls:'mode-loss',       valCls:'neg'  };
  }
  const _pos  = wlEntry && wlEntry.position;
  const _mode = derivePositionMode(_pos);
  const _posCardHtml = (_pos && _pos.hasPosition === true)
    ? `<div class="mp-pos ${_mode.cls}">
         <div class="mp-pos-label">POSITION CONTEXT</div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Holding</span><span class="mp-pos-val">Yes</span></div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Position value</span><span class="mp-pos-val">${_pos.positionValue !== null ? fmtMoney(_pos.positionValue) : 'Not entered'}</span></div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Current P/L</span><span class="mp-pos-val ${_mode.valCls}">${_pos.pnlPercent !== null ? fmtPnl(_pos.pnlPercent) : 'Not entered'}</span></div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Mode</span><span class="mp-pos-val ${_mode.valCls}">${_mode.label}</span></div>
       </div>`
    : `<div class="mp-pos ${_mode.cls}">
         <div class="mp-pos-label">POSITION CONTEXT</div>
         <div class="mp-pos-muted">No position — fresh-entry framing applies</div>
       </div>`;

  // 7A-3: Position-aware framing — render-only, local-only, never sent to AI/API.
  // Mirrors Position Context mode color so the two cards read as a single section.
  function derivePositionTake(p, technical_setup, mode) {
    if (!mode || mode.key === 'fresh') return null;
    if (mode.key === 'unknown') return 'Position open / P/L not entered — fill in current P/L for tailored framing.';
    const pnl = fmtPnl(p.pnlPercent);
    const ts  = technical_setup || '';
    const ppt = p.partialProfitTaken === true;
    if (mode.key === 'big-winner') {
      const opener = `Existing big winner, ${pnl} unrealized gain.`;
      if (ppt) return opener + ' Runner already established — hold the runner and avoid re-adding while extended.';
      if (ts === 'extended_near_ath') return opener + ' Prioritize profit protection: hold core, consider trimming partial profits into strength, keep a runner, and avoid adding unless price consolidates or reclaims with controlled risk.';
      if (ts === 'pullback_in_uptrend') return opener + ' Pullback inside uptrend — hold core; add only if size allows and a reclaim confirms on rising relative strength.';
      if (ts === 'below_key_mas' || ts === 'breakdown_risk') return opener + ' Trend is weakening — lock in partial profits, tighten stops, and avoid adding.';
      return opener + ' Prioritize profit protection: hold core, consider partial trim into strength, and avoid adding without a controlled setup.';
    }
    if (mode.key === 'profitable') {
      const opener = `Profitable position, ${pnl} unrealized gain.`;
      if (ts === 'extended_near_ath') return opener + ' Hold core; resist adding while extended. Let trend work; consider partial trim if extension grows.';
      if (ts === 'pullback_in_uptrend') return opener + ' Hold core; add only on confirmed reclaim with risk defined.';
      if (ts === 'below_key_mas' || ts === 'breakdown_risk') return opener + ' Trend deteriorating — reduce on bounces or tighten stops.';
      return opener + ' Hold core, let the trend work, and add only on a valid setup.';
    }
    if (mode.key === 'flat') {
      const opener = `Flat position, ${pnl}.`;
      if (ts === 'pullback_in_uptrend' || ts === 'support_test') return opener + ' Decision zone — wait for reclaim confirmation before adding; avoid overreacting on noise.';
      if (ts === 'extended_near_ath') return opener + ' Decision zone but price is extended — wait for a pullback or controlled setup before sizing up.';
      if (ts === 'below_key_mas' || ts === 'breakdown_risk') return opener + ' Technical structure weak — define an invalidation level and avoid adding.';
      return opener + ' Decision zone — let the technical setup dictate; avoid overreacting.';
    }
    if (mode.key === 'loss') {
      const opener = `Existing losing position, ${pnl}.`;
      if (ts === 'below_key_mas' || ts === 'breakdown_risk') return opener + ' Reduce risk: reassess thesis, avoid adding, and define a clear invalidation/exit plan.';
      if (ts === 'support_test' || ts === 'pullback_in_uptrend') return opener + ' Watch for reclaim before adding; define invalidation and respect it.';
      return opener + ' Prioritize risk control: reassess thesis, avoid adding until technical reclaim, and define a clear invalidation/exit plan.';
    }
    return null;
  }
  const _positionTake = derivePositionTake(_pos, item.technical_setup, _mode);
  const _positionTakeHtml = _positionTake !== null
    ? `<div class="mp-pos-take ${_mode.cls}">
         <div class="mp-pos-take-label">POSITION TAKE</div>
         <div class="mp-pos-take-text">${_positionTake}</div>
       </div>`
    : '';

  function fmtMA(sma) {
    if (sma === null || sma === undefined) return '—';
    return '$' + sma.toFixed(2);
  }
  function maState(pct) {
    if (pct === null || pct === undefined) return null; // unknown
    if (pct > 1)  return 'pos'; // Above
    if (pct > -3) return 'warn'; // Near
    return 'neg'; // Below
  }
  function maLabel(pct) {
    if (pct === null || pct === undefined) return '—';
    if (pct > 1)  return 'Above';
    if (pct > -3) return 'Near';
    return 'Below';
  }
  function rsLabel(val) {
    if (val === null || val === undefined) return null;
    if (val > 3)  return { lbl: 'OUTPERFORM', cls: 'pos' };
    if (val > -3) return { lbl: 'IN LINE',    cls: 'neutral-v' };
    return           { lbl: 'UNDERPERFORM', cls: 'warn' };
  }

  // Kick off async snapshot fetch/refresh (no-op if already cached)
  // Re-renders the panel when data arrives if this ticker is still selected
  refreshTechPanel(item.ticker, dispEtf, item._verifiedPrice);

  // 7B-2B: hardcoded summary-substring catalyst dictionary removed.
  // The CATALYSTS panel now reads real ticker-specific rows from item._catalysts
  // (attached by orchestrate in 7B-2A). Row builder is defined just before
  // panel.innerHTML so it can use the _esc helper. The fallback ternary in the
  // render block continues to handle _catalystDataMissing, _hasStructuredCatalysts,
  // and pre-7B-2A persisted results without _catalysts.

  // Sparkline removed in Phase 2b header

  // Data source + last-updated indicators
  const _src = item._dataSource || item._source || '';
  const dataSource  = _src ? (_src.toLowerCase().includes('yahoo') ? 'yahoo' :
                               _src.toLowerCase().includes('alpha') ? 'alphavantage' :
                               _src.toLowerCase()) : '';
  const _ts = item._timestamp || item._orchestratedAt || '';
  // EG-18: scan age — null only on parse error; ≤0 means future/clock-skew
  const _scanAgeMs = (function() {
    if (!_ts) return null;
    try { var _d = new Date(_ts); var _a = Date.now() - _d.getTime(); return isFinite(_a) ? _a : null; } catch(_e) { return null; }
  })();
  const _scanAgeCls = !_ts                                    ? ''
    : (_scanAgeMs === null || _scanAgeMs <= 0)                ? ' ph-updated--vhi'
    : _scanAgeMs > 72 * 3600000                               ? ' ph-updated--vhi'
    : _scanAgeMs > 24 * 3600000                               ? ' ph-updated--stale'
    :                                                           '';
  let lastUpdated = '';
  if (_ts) {
    try {
      const d = new Date(_ts);
      if (isNaN(d.getTime())) { lastUpdated = 'timestamp unclear'; }
      else {
        const _tsNow = new Date();
        const _tsSD = d.getFullYear()===_tsNow.getFullYear()&&d.getMonth()===_tsNow.getMonth()&&d.getDate()===_tsNow.getDate();
        lastUpdated = _tsSD ? d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}) : d.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' · '+d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'});
      }
    } catch(e) { lastUpdated = ''; }
  }

  // Watchlist metadata for name / exchange / sector (Phase 1 schema)
  // Extended-hours: read session-only cache; no item/localStorage fields touched
  const _extC      = hasData ? (_extendedMktCache[item.ticker] || null) : null;
  const _ms        = _extC ? _extC.marketState : null;

  // Market status — prefer fresh Yahoo marketState; fall back to time heuristic
  const _now     = new Date();
  const _etHour  = (_now.getUTCHours() - 4 + 24) % 24; // rough ET offset
  const _isOpen  = _etHour >= 9.5 && _etHour < 16 && _now.getUTCDay() >= 1 && _now.getUTCDay() <= 5;
  const mktLabel = _ms === 'REGULAR' ? 'Market open · closes 4:00 PM ET'
                 : _ms === 'PRE'     ? 'Pre-market'
                 : _ms === 'POST'    ? 'After-hours'
                 : _ms === 'CLOSED'  ? 'Market closed'
                 : (_isOpen ? 'Market open · closes 4:00 PM ET' : 'Market closed');
  const mktCls   = _ms === 'REGULAR' ? 'open' : _ms ? 'closed' : (_isOpen ? 'open' : 'closed');
  // EG-18: display-only pill qualification — mirrors Change A classification exactly
  const _scanAgeSuspicious   = !!_ts && (_scanAgeMs === null || _scanAgeMs <= 0);
  const _scanAgeVeryStale    = !!_ts && _scanAgeMs !== null && _scanAgeMs > 72 * 3600000;
  const _scanAgeNeedsContext = _scanAgeSuspicious || _scanAgeVeryStale;
  const _mktDspCls = _scanAgeNeedsContext ? 'closed' : mktCls;
  const _mktLbl    = !_scanAgeNeedsContext ? mktLabel
    : _scanAgeMs === null                  ? 'Data timestamp unclear'
    : _scanAgeMs <= 0                      ? 'Data timestamp needs review'
    : lastUpdated                          ? 'Data from ' + lastUpdated
    :                                        'Data from prior scan';

  const _todayLbl  = _ms === 'REGULAR' ? 'today'
                   : (_ms === 'PRE' || _ms === 'POST' || _ms === 'CLOSED') ? 'regular close'
                   : 'regular price';
  const _showExt   = _ms === 'PRE' || _ms === 'POST';
  const _extPrice  = _ms === 'PRE'  ? _extC.preMarketPrice
                   : _ms === 'POST' ? _extC.postMarketPrice  : null;
  const _extChgPct = _ms === 'PRE'  ? _extC.preMarketChangePercent
                   : _ms === 'POST' ? _extC.postMarketChangePercent : null;

  // After a ↻ refresh during PRE/POST, show the live regular-market price/change in the
  // primary row so it matches the base used to calculate the extended-hours row
  if (_showExt && _extC) {
    if (typeof _extC.regularPrice    === 'number') price = `$${_extC.regularPrice.toFixed(2)}`;
    if (typeof _extC.regularChangePct === 'number') chg  = _extC.regularChangePct;
  }

  // Avatar initials (up to 2 chars)
  const avatarTxt = item.ticker.slice(0, 2);
  const avatarCls = sent === 'positive' ? 'sent-pos' : sent === 'negative' ? 'sent-neg' : 'sent-neu';

  // Change string
  const chgSign   = chg === null ? '' : chg >= 0 ? '+' : '';
  const chgAmt    = chg !== null && item._verifiedPrice
    ? (chg >= 0 ? '+' : '') + ((item._verifiedPrice - item._verifiedPrice / (1 + chg/100))).toFixed(2)
    : null;
  const chgAmtStr = chgAmt !== null ? `▲${Math.abs(parseFloat(chgAmt)).toFixed(2)}` : '';
  const chgPctStr = chg !== null ? `(${chgSign}${chg.toFixed(2)}%)` : '—';
  const chgDir    = chg !== null && chg < 0 ? '▼' : chg !== null && chg > 0 ? '▲' : '';
  const chgCls2         = chg === null ? 'neu' : chg > 0 ? 'pos' : chg < 0 ? 'neg' : 'neu';
  const _displayPriceBase = (_extC && typeof _extC.regularPrice === 'number') ? _extC.regularPrice : (item._verifiedPrice || 0);
  // Phase 6A-1: escape AI-generated prose fields before HTML insertion
  const _esc = s => s ? String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;') : '';

  // 7B-2B: build real catalyst rows from item._catalysts (attached by 7B-2A orchestrate).
  // Priority order: analystActions → bullish → bearish → macro → earnings (only if room).
  // Cap at 5 visible rows. All Perplexity-sourced strings pass through _esc + truncation.
  // When _catalysts is absent (pre-7B-2A persisted results) or empty, catalystRows stays
  // empty and the render block falls through to the existing _catalystDataMissing /
  // _hasStructuredCatalysts / "No verified catalysts" ternary.
  const _trunc70 = s => { s = String(s == null ? '' : s); return s.length > 70 ? s.slice(0, 67) + '…' : s; };
  const _actionPosVerbs = ['raised','boosted','hiked','initiated','started','resumed','upgraded','reinstated'];
  const _actionNegVerbs = ['cut','lowered','reduced','trimmed','downgraded'];
  const _actionNeuVerbs = ['maintained','reiterated','set','launched'];
  const _actionStateOf = v => {
    const vv = String(v || '').toLowerCase();
    if (_actionPosVerbs.includes(vv)) return { state: 'POSITIVE', cls: 'pos' };
    if (_actionNegVerbs.includes(vv)) return { state: 'RISK',     cls: 'neg' };
    if (_actionNeuVerbs.includes(vv)) return { state: 'WATCH',    cls: 'warn' };
    return { state: 'WATCH', cls: 'warn' };
  };
  const _c = item._catalysts || null;
  const catalystRows = [];
  if (_c) {
    const ROW_CAP = 5;
    for (const a of (_c.analystActions || [])) {
      if (catalystRows.length >= ROW_CAP) break;
      const { state, cls } = _actionStateOf(a && a.action);
      const bank = _esc(_trunc70(a && a.bank));
      const action = _esc(String((a && a.action) || '').toLowerCase());
      const target = (a && typeof a.target === 'number') ? a.target : null;
      const lbl = (bank && action && target !== null)
        ? `${bank} ${action} PT $${target}`
        : _esc(_trunc70((a && a.raw) || 'Analyst action'));
      catalystRows.push({ cls, lbl, state });
    }
    for (const s of (_c.bullish || [])) {
      if (catalystRows.length >= ROW_CAP) break;
      catalystRows.push({ cls: 'pos',       lbl: _esc(_trunc70(s)), state: 'POSITIVE' });
    }
    for (const s of (_c.bearish || [])) {
      if (catalystRows.length >= ROW_CAP) break;
      catalystRows.push({ cls: 'neg',       lbl: _esc(_trunc70(s)), state: 'RISK' });
    }
    for (const s of (_c.macro || [])) {
      if (catalystRows.length >= ROW_CAP) break;
      catalystRows.push({ cls: 'warn',      lbl: _esc(_trunc70(s)), state: 'MACRO' });
    }
    const _earn = _c.earnings;
    if (catalystRows.length < ROW_CAP && _earn && !/^(NONE|N\/?A|-|—|unknown)\b/i.test(String(_earn).trim())) {
      catalystRows.push({ cls: 'neutral-v', lbl: _esc(_trunc70(_earn)), state: 'EARNINGS' });
    }
  }

  // 9A-1: build news driver rows from item.news (already in pt_results; display-only).
  const _trunc150 = s => { s = String(s == null ? '' : s); return s.length > 150 ? s.slice(0, 147) + '…' : s; };
  const _ND_TAGS = ['PRIMARY', 'SECONDARY', 'BACKGROUND'];
  const _newsRows = (Array.isArray(item.news) ? item.news : []).slice(0, 3).map((s, i) => {
    const str = String(s || '').trim();
    if (!str) return null;
    const m = str.match(/^(Primary|Secondary|Background)\s*:\s*/i);
    const tag = m ? m[1].toUpperCase() : (_ND_TAGS[i] || 'NOTE');
    const text = _trunc150(m ? str.slice(m[0].length).trim() : str);
    return text ? { tag, text: _esc(text) } : null;
  }).filter(Boolean);

  const _tsAssessMap = {
    healthy_uptrend:          '20 > 50 > 150 — Healthy uptrend, price above key moving averages',
    bullish_stack:            '20 > 50 > 150 — Healthy uptrend, price above key moving averages',
    healthy_uptrend_near_ath: 'Healthy uptrend near its 1-year high — trend intact but extended',
    extended_near_ath:        'Price extended above key moving averages and near its 1-year high',
    pullback_in_uptrend:      'Pullback within an uptrend — watch for support to hold',
    pullback_to_ma50:         'Pulling back toward the 50-day — watch for support hold',
    pullback_to_ma20:         'Pulling back toward the 20-day — watching for bounce',
    below_key_mas:            'Below key moving averages — structure is bearish',
    mixed:                    'Mixed MA alignment — no clear directional stack',
  };
  const _maStackKey = _panelSetup === 'healthy_uptrend' || _panelSetup === 'bullish_stack'; // R-2 (Entry 35): the two setups whose text claims a stack
  const _maStackAll = [_panelSnap.sma20, _panelSnap.sma50, _panelSnap.sma150].every(Number.isFinite);
  const _maStacked  = _maStackAll && _panelSnap.sma20 > _panelSnap.sma50 && _panelSnap.sma50 > _panelSnap.sma150;
  const _tsAssess = _panelSetup === 'unknown' ? '' : !_maStackKey ? (_tsAssessMap[_panelSetup] || '') : _maStacked ? (_tsAssessMap[_panelSetup] || '') : _maStackAll ? 'Price above all key moving averages — healthy uptrend; averages not fully stacked' : 'Healthy uptrend — price above key moving averages';
