  const _trunc70 = s => { s = String(s == null ? '' : s); return s.length > 70 ? s.slice(0, 67) + '…' : s; };
  const _actionPosVerbs = ['raised','boosted','hiked','initiated','started','resumed','upgraded','reinstated'];
  const _actionNegVerbs = ['cut','lowered','reduced','trimmed','downgraded'];
