_isValidScanResult.source:
function _isValidScanResult(r) {
  const ok = r &&
    typeof r.ticker === 'string' && r.ticker.length > 0 &&
    ((typeof r.sentiment_score === 'number' && r.sentiment_score >= 0 && r.sentiment_score <= 100) || (r.sentiment_score === null && r._aiUnavailable === true)) && // R-3 (Entry 36): a failed AI analysis persists as null
    typeof r.summary === 'string' && r.summary.length > 50 &&
    ['positive','negative','neutral'].includes(r.sentiment) &&
    !r.summary.includes('=== PERPLEXITY') &&
    !r.summary.includes('%%NEWS_CONTEXT') &&
    !r.summary.includes('__raw__');
  if (!ok) console.warn('[PT] REJECTED malformed result:', JSON.stringify(r).slice(0,120));
  return ok;
}

_srGroupResults.source:
function _srGroupResults(source) {
  const items = source.slice().sort(_ptScoreCmp); // R-5 (Entry 37, ruling B1): Pulse-only ordering; equal scores keep source order
  // display order: Strong Setup → Watch → Extended / near 1Y high → Caution → Analysis failed — rescan (R-3, Entry 36)
  const groups = [
    { name: 'Strong Setup',   items: [] },
    { name: 'Watch',          items: [] },
    { name: 'Extended / near 1Y high', items: [] },
    { name: 'Caution',        items: [] },
    { name: 'Analysis failed — rescan', items: [] },
  ];
  items.forEach(r => {
    const sc = _ptScoreNorm(r.sentiment_score);
    const ts = r.technical_setup || '';
    if (r._aiUnavailable === true)                groups[4].items.push(r); // R-3 (Entry 36): a failed AI analysis is never ranked by setup
    else if (_SR_BULLISH_TIER.has(ts) && sc !== null && sc >= 55)  groups[0].items.push(r);
    else if (ts === 'extended_near_ath')         groups[2].items.push(r);
    else if (_SR_BEARISH_TIER.has(ts))           groups[3].items.push(r);
    else                                          groups[1].items.push(r);
  });
  return groups;
}

analyzeChunk.source:
async function analyzeChunk(batch, today) {
  // Enforce single-ticker mode — split multi-ticker into sequential single runs
  if (batch.length > 1) {
    console.log(`[PT] Multi-ticker batch: running sequentially for isolation`);
    const allResults = [];
    for (const sym of batch) {
      const r = await analyzeChunk([sym], today);
      allResults.push(...r);
    }
    return allResults;
  }
  console.log(`[PT] analyzeChunk START: ${batch[0]}`);
  let rawText = '', pplxData = {}, stockData = {}, _anthropicError = null;

  // 7B-3B3: bounded Perplexity retry helpers (scope-local; no window.* exposure).
  // Used to detect weak Perplexity responses and decide whether to retry once.
  const _NONE_RE_7B3B3 = /^(NONE|N\/?A|-|—|unknown)\b/i;
  const _isNoneVal_7B3B3 = v => !v || _NONE_RE_7B3B3.test(String(v).trim());
  const _countSummary = (p) => {
    if (!p) return '0/0/0/0/0';
    const a = p.analystActions?.length || 0;
    const b = p.bullishCatalysts?.length || 0;
    const x = p.bearishCatalysts?.length || 0;
    const m = p.macroDrivers?.length || 0;
    const e = (p.earnings && !_isNoneVal_7B3B3(p.earnings)) ? 1 : 0;
    return `${b}/${x}/${m}/${a}/${e}`;
  };
  const _detectWeakPerplexity = (raw, p, parsedFrom) => {
    if (parsedFrom === 'empty')     return 'empty-parse';
    if (p && p._allNone === true)   return 'all-none';
    const rawLen = (raw || '').length;
    const aCount = p?.analystActions?.length   || 0;
    const bCount = p?.bullishCatalysts?.length || 0;
    const xCount = p?.bearishCatalysts?.length || 0;
    const mCount = p?.macroDrivers?.length     || 0;
    const earningsMeaningful = p?.earnings && !_isNoneVal_7B3B3(p.earnings);
    if (rawLen < 500 && aCount === 0 && bCount === 0 && xCount === 0 && mCount === 0 && !earningsMeaningful) {
      return 'short-raw';
    }
    return null;
  };
  const _retryIsBetter = (first, retry, firstRawLen, retryRawLen) => {
    if (!retry) return false;
    if (!first) return true;
    const countOf = (p) => {
      if (!p) return 0;
      const e = (p.earnings && !_isNoneVal_7B3B3(p.earnings)) ? 1 : 0;
      return (p.analystActions?.length || 0) + (p.bullishCatalysts?.length || 0)
           + (p.bearishCatalysts?.length || 0) + (p.macroDrivers?.length || 0) + e;
    };
    const fc = countOf(first);
    const rc = countOf(retry);
    if (rc > fc) return true;
    // Tie-breaker: retry raw must be materially longer (≥200 chars) to displace first.
    if (rc === fc && retryRawLen > firstRawLen + 200) return true;
    return false;
  };
  // 7B-4a: parsed catalyst counts for telemetry (memory-only). Safe on null input.
  const _parsedCountsOf = (p) => ({
    bullish:  p?.bullishCatalysts?.length || 0,
    bearish:  p?.bearishCatalysts?.length || 0,
    macro:    p?.macroDrivers?.length     || 0,
    analyst:  p?.analystActions?.length   || 0,
    earnings: (p?.earnings && !_isNoneVal_7B3B3(p.earnings)) ? 1 : 0
  });

  stockData = await fetchBatchStockData(batch);
  batch.forEach(sym => { _fetchTimestamps[sym] = Date.now(); });
  batch.forEach(sym => {
    const d = stockData[sym];
    if (d) console.log(`[PT] Market OK: ${sym} $${d.price} ${d.change_percent}% [${d.source}]`);
    else   console.warn(`[PT] Market MISS: ${sym}`);
  });
  const _crFetchPromise9B = _crFetchForScan(batch[0]); // 9B-2B: fire CR prefetch in parallel with Perplexity/Anthropic
  const stockContext = formatStockContext(stockData);

  // Phase 6A-1: Compute technical snapshot before Anthropic call
  // computeTechnicalSnapshot caches results in _techCache; failure is non-fatal
  const _sym6a = batch[0];
  const _wl6a  = findTicker(_sym6a);
  let _techSnap6a    = {};
  let _setupState6a  = 'unknown';
  try {
    _techSnap6a   = await computeTechnicalSnapshot(_sym6a, _wl6a?.sectorEtf || '', stockData[_sym6a]?.price || null);
    _setupState6a = classifyTechnicalSetup(_techSnap6a);
    console.log(`[PT] Tech setup for ${_sym6a}: ${_setupState6a}`);
  } catch(e) {
    console.warn(`[PT] computeTechnicalSnapshot failed for ${_sym6a} — continuing with unknown:`, e.message);
  }
  const _techSnapshotText6a = buildTechSnapshotBlock(_sym6a, _techSnap6a, _setupState6a);

  // Per-ticker isolation: call Perplexity once per ticker, never batch
  for (const sym of batch) {
    const _pplxCallStart = Date.now(); // 7B-4a: timing baseline (covers success and error paths)
    try {
      // 7B-1: fetch now returns { raw, sources, _telemetry }; parser attaches sources per ticker
      const { raw, sources, _telemetry } = await fetchPerplexityContext([sym]); // single ticker only
      const parsed = parsePerplexityContext(raw, sources);
      // 7B-3D0: memory-only debug snapshot — capture raw + parsed per ticker. NEVER persisted.
      if (!window._pplxDebug) window._pplxDebug = {};
      window._pplxDebug[sym] = {
        rawText:      raw,
        rawLength:    (raw || '').length,
        sourcesCount: Array.isArray(sources) ? sources.length : 0,
        parsed:       parsed[sym] || parsed['__raw__'] || null,
        parsedFrom:   parsed[sym] ? 'ticker-header' : (parsed['__raw__'] ? '__raw__-fallback' : 'empty'),
        capturedAt:   new Date().toISOString(),
        // 7B-4a: per-call/per-ticker telemetry (memory-only; never persisted)
        endpoint:       _telemetry?.endpoint || 'perplexity-proxy',
        model:          _telemetry?.model    || 'sonar-pro',
        startedAt:      _telemetry?.startedAt  ?? _pplxCallStart,
        finishedAt:     _telemetry?.finishedAt ?? Date.now(),
        latencyMs:      _telemetry?.latencyMs  ?? (Date.now() - _pplxCallStart),
        callCount:      1,
        retryAttempted: false,
        retryCount:     0,
        retryReason:    null,
        retryImproved:  false,
        retryLatencyMs: null,
        parsedCounts:   _parsedCountsOf(parsed[sym] || parsed['__raw__'] || null),
        unavailable:    false,
        fallbackUsed:   false,
        errorReason:    null,
        // 7B-4 (patch): explicit reliability state — memory-only. 'stale' reserved for future use.
        responseState:    'available',
        recoveredByRetry: false
      };
      // 7B-3B3: bounded retry on weak Perplexity response (one retry max per ticker).
      // Only triggers for empty-parse / all-none / short-raw cases. Network errors fall
      // through to the existing catch(e) block below and are NOT retried here.
      const _firstParsedTicker = parsed[sym] || parsed['__raw__'] || null;
      const _firstParsedFrom   = window._pplxDebug[sym].parsedFrom;
      const _weakReason        = _detectWeakPerplexity(raw, _firstParsedTicker, _firstParsedFrom);
      let finalParsed = parsed;
      if (_weakReason) {
        console.warn(`[PT] Perplexity weak response for ${sym} (${_weakReason}, rawLength=${(raw||'').length}); retrying once.`);
        try {
          const _retry        = await fetchPerplexityContext([sym]);
          const _retryParsed  = parsePerplexityContext(_retry.raw, _retry.sources);
          const _retryTicker  = _retryParsed[sym] || _retryParsed['__raw__'] || null;
          const _useRetry     = _retryIsBetter(_firstParsedTicker, _retryTicker, (raw||'').length, (_retry.raw||'').length);
          window._pplxDebug[sym].retryAttempted = true;
          window._pplxDebug[sym].retryReason    = _weakReason;
          window._pplxDebug[sym].firstRawLength = (raw || '').length;
          window._pplxDebug[sym].retryRawLength = (_retry.raw || '').length;
          window._pplxDebug[sym].firstParsed    = _firstParsedTicker;
          window._pplxDebug[sym].retryParsed    = _retryTicker;
          window._pplxDebug[sym].retryImproved  = _useRetry;
          // 7B-4a: retry telemetry (memory-only)
          window._pplxDebug[sym].callCount      = 2;
          window._pplxDebug[sym].retryCount     = 1;
          window._pplxDebug[sym].retryLatencyMs = _retry._telemetry?.latencyMs ?? null;
          if (_useRetry) {
            finalParsed  = _retryParsed;
            // Update canonical _pplxDebug fields to reflect the winning attempt.
            window._pplxDebug[sym].rawText      = _retry.raw;
            window._pplxDebug[sym].rawLength    = (_retry.raw || '').length;
            window._pplxDebug[sym].sourcesCount = Array.isArray(_retry.sources) ? _retry.sources.length : 0;
            window._pplxDebug[sym].parsed       = _retryTicker;
            window._pplxDebug[sym].parsedFrom   = _retryParsed[sym] ? 'ticker-header' : (_retryParsed['__raw__'] ? '__raw__-fallback' : 'empty');
            window._pplxDebug[sym].parsedCounts = _parsedCountsOf(_retryTicker);
            // 7B-4 (patch): retry improved the response (memory-only)
            window._pplxDebug[sym].responseState    = 'recovered';
            window._pplxDebug[sym].recoveredByRetry = true;
            console.warn(`[PT] Perplexity retry improved ${sym}: first counts=${_countSummary(_firstParsedTicker)} retry counts=${_countSummary(_retryTicker)} (b/x/m/a/e)`);
          } else {
            // 7B-4 (patch): retry ran but did not improve — response stays weak (memory-only)
            window._pplxDebug[sym].responseState    = 'weak';
            window._pplxDebug[sym].recoveredByRetry = false;
            console.warn(`[PT] Perplexity retry still weak for ${sym}: first counts=${_countSummary(_firstParsedTicker)} retry counts=${_countSummary(_retryTicker)} — keeping first`);
          }
        } catch (_retryErr) {
          console.warn(`[PT] Perplexity retry threw for ${sym}: ${_retryErr.message}`);
          window._pplxDebug[sym].retryAttempted = true;
          window._pplxDebug[sym].retryReason    = _weakReason;
          window._pplxDebug[sym].firstRawLength = (raw || '').length;
          window._pplxDebug[sym].firstParsed    = _firstParsedTicker;
          window._pplxDebug[sym].retryImproved  = false;
          window._pplxDebug[sym].retryError     = _retryErr.message;
          // 7B-4a: retry telemetry (memory-only) — retry threw; first attempt is kept
          window._pplxDebug[sym].callCount      = 2;
          window._pplxDebug[sym].retryCount     = 1;
          // 7B-4 (patch): retry threw → did not improve; response stays weak (memory-only)
          window._pplxDebug[sym].responseState    = 'weak';
          window._pplxDebug[sym].recoveredByRetry = false;
        }
      }
      // Merge into pplxData — only under the correct ticker key.
      // 7B-3B3: consume finalParsed (winning attempt).
      if (finalParsed[sym]) {
        pplxData[sym] = finalParsed[sym];
        console.log(`[PT] Perplexity OK for ${sym}: ${finalParsed[sym].analystActions?.length || 0} analyst actions, ${finalParsed[sym].macroDrivers?.length || 0} macro, ${finalParsed[sym].sources?.length || 0} sources`);
      } else if (finalParsed['__raw__']) {
        // Fallback: tag raw context under the correct ticker
        pplxData[sym] = { ...finalParsed['__raw__'], _ticker: sym };
        console.log(`[PT] Perplexity raw fallback for ${sym}`);
      }
    } catch(e) {
      console.warn(`[PT] Perplexity failed for ${sym}:`, e.message);
      // 6B-1: mark ticker as upstream-unavailable so downstream can distinguish from all-NONE
      pplxData[sym] = { _unavailable: true, _error: e.message, analystActions: [], bullishCatalysts: [], bearishCatalysts: [], macroDrivers: [] };
      // 7B-4a: telemetry for the unavailable/error path (memory-only; never persisted)
      if (!window._pplxDebug) window._pplxDebug = {};
      window._pplxDebug[sym] = {
        ...(window._pplxDebug[sym] || {}),
        endpoint:     'perplexity-proxy',
        model:        'sonar-pro',
        startedAt:    _pplxCallStart,
        finishedAt:   Date.now(),
        latencyMs:    Date.now() - _pplxCallStart,
        callCount:    (window._pplxDebug[sym]?.callCount) || 1,
        rawLength:    (window._pplxDebug[sym]?.rawLength) || 0,
        sourcesCount: (window._pplxDebug[sym]?.sourcesCount) || 0,
        parsedCounts: (window._pplxDebug[sym]?.parsedCounts) || _parsedCountsOf(null),
        unavailable:  true,
        fallbackUsed: (window._pplxDebug[sym]?.fallbackUsed) || false,
        errorReason:  e.message,
        // 7B-4 (patch): explicit reliability state for the failure path (memory-only).
        // No retry is attempted on fetch failure, so retryAttempted/retryCount stay false/0.
        responseState:    'unavailable',
        recoveredByRetry: false,
        retryAttempted:   false,
        retryCount:       0,
        capturedAt:   new Date().toISOString()
      };
    }
  }
  console.log(`[PT] Perplexity parsed tickers: ${Object.keys(pplxData).join(',') || 'none'}`);

  // Debug: console only — never expose to UI
  console.log('[PT] stockContext length:', stockContext.length);
  console.log('[PT] pplxData keys:', Object.keys(pplxData).join(','));

  try {
    rawText = await fetchAnthropicAnalysis(batch, today, stockContext + '\n%%NEWS_CONTEXT_START%%\n' + JSON.stringify(pplxData), _techSnapshotText6a);
  } catch (e) {
    _anthropicError = e;
    console.warn(`[PT] Anthropic failed for ${batch[0]}, using market-data fallback:`, e.message);
  }

  console.log('[PT] Claude raw response length:', rawText.length);
  const parsed = parseJSON(rawText);
  let raw = parsed.results || [];

  // 7B-1.5: symbol consistency check — Anthropic occasionally returns a result
  // for the wrong ticker. Single-ticker isolation means batch.length === 1 here.
  if (raw.length > 0 && batch.length === 1 && raw[0].ticker && raw[0].ticker.toUpperCase() !== batch[0].toUpperCase()) {
    console.warn(`[PT] Ticker mismatch: expected ${batch[0]}, got ${raw[0].ticker} — treating as parse-failed`);
    raw = [];
  }

  // 7B-1.5: Anthropic returned content but parseJSON yielded 0 results → retry once.
  // Bounded to a single retry per ticker. Same prompt, no max_tokens change.
  let _retryAttempted = false;
  if (raw.length === 0 && !_anthropicError && rawText && rawText.length > 100) {
    console.warn(`[PT] parseEmpty for ${batch[0]} (rawLen=${rawText.length}) — retrying Anthropic once`);
    _retryAttempted = true;
    try {
      const retryText = await fetchAnthropicAnalysis(batch, today, stockContext + '\n%%NEWS_CONTEXT_START%%\n' + JSON.stringify(pplxData), _techSnapshotText6a);
      console.log(`[PT] Retry: response length ${retryText.length}`);
      const retryParsed = parseJSON(retryText);
      const retryRaw = retryParsed.results || [];
      const retryOk = retryRaw.length > 0 && (!retryRaw[0].ticker || retryRaw[0].ticker.toUpperCase() === batch[0].toUpperCase());
      if (retryOk) {
        raw = retryRaw;
        console.log(`[PT] Retry resolved: ${raw.length} result(s) for ${batch[0]}`);
      } else {
        console.warn(`[PT] Retry still empty/mismatched for ${batch[0]} — falling through to safe fallback`);
      }
    } catch (retryErr) {
      console.warn(`[PT] Retry threw for ${batch[0]}: ${retryErr.message}`);
      _anthropicError = retryErr;
    }
  }

  // ── Anthropic fallback ────────────────────────────────────────────────────
  // Build a minimal fallback result per ticker so verified price, technical
  // panels, and Perplexity context are still preserved and persisted to
  // pt_results. Triggers when Anthropic erred, returned empty, or both the
  // first attempt and retry produced 0 parseable results.
  // 7B-1.5: condition broadened from "&& _anthropicError" so parse-fail also
  // produces a safe synthetic result instead of silently dropping the ticker.
  // Raw API error message is logged to console only — never surfaced in UI.
  if (raw.length === 0) {
    raw = batch.map(sym => {
      const wlEntry = findTicker(sym);
      // Preserve any Perplexity-derived analyst alerts if available
      const pplxAlerts = (pplxData[sym]?.analystActions?.length)
        ? pplxData[sym].analystActions.map(a => ({
            type: 'normal',
            text: `${a.bank} price target $${a.target} — verify if recent`
          }))
        : [];
      const summaryNet = 'AI analysis unavailable — market data shown only. Technical panels reflect verified price and candle data. No AI-generated summary is available for this scan.';
      const summaryParse = 'AI response could not be parsed after retry — market data and technical panels shown only. No AI-generated summary is available for this scan.';
      return {
        ticker: sym,
        company_name: (wlEntry && wlEntry.name) || sym,
        sentiment: 'neutral',
        sentiment_score: null,
        summary: _anthropicError ? summaryNet : (_retryAttempted ? summaryParse : summaryNet),
        alerts: pplxAlerts,
        news: [],
        _aiUnavailable: true,
        _aiParseFailed: !_anthropicError && _retryAttempted
      };
    });
    const _reason = _anthropicError ? 'anthropic-error' : (_retryAttempted ? 'parse-fail-after-retry' : 'parse-empty-no-retry');
    console.warn(`[PT] Fallback results built for ${batch.join(',')} (reason: ${_reason})`);
    // 7B-4a: mark per-ticker telemetry that the Anthropic synthetic fallback was used (memory-only)
    batch.forEach(sym => { if (window._pplxDebug && window._pplxDebug[sym]) window._pplxDebug[sym].fallbackUsed = true; });
  }

  await Promise.allSettled([_crFetchPromise9B]); // 9B-2B: settle CR prefetch before nudge; side-effect only, never throws
  const orchestrated = orchestrate(raw, pplxData, stockData, { [_sym6a]: _techSnap6a });

  // 7B-3D0: mirror the memory-only debug accumulator into _lastRunState for ergonomic access
  window._lastRunState = { stockData, pplxData, techSnap: _techSnap6a, setupState: _setupState6a, runId: Date.now(), timestamp: new Date().toISOString(), pplxDebug: window._pplxDebug || {} };

  const resultsWithPct = orchestrated.map(item => {
    const mkt = stockData[item.ticker];
    return mkt ? { ...item, _changePct: mkt.change_percent } : item;
  });
  // Terminal-chain integrity slice (2026-08-08): applyCapitalReturnsNudge
  // removed from the active scoring chain per Main Control ruling — the
  // function remains in source, uncalled, for future non-scoring/display
  // use. Newly scored items no longer receive _crNudge.
  return enforceScoreConsistency(resultsWithPct, JSON.stringify(pplxData));
}

orchestrate.source:
function orchestrate(claudeResults, pplxData, stockData, techSnaps) {
  return claudeResults.map(item => {
    const sym = item.ticker;
    const mkt  = stockData?.[sym];
    const pplx = pplxData?.[sym] || pplxData?.['__raw__'];

    // Fix B: watchlist identity is authoritative — override AI-provided company_name
    const _wlIdentity = findTicker(sym);
    if (_wlIdentity?.name) item.company_name = _wlIdentity.name;

    delete _extendedMktCache[sym];
    if (mkt) {
      item._verifiedPrice = mkt.price;
      item._verifiedChangePct = mkt.change_percent;
      item._dataSource = mkt.source;
      if (mkt.source === 'yahoo' && mkt.marketState) {
        _extendedMktCache[sym] = {
          marketState:              mkt.marketState,
          preMarketPrice:           mkt.preMarketPrice           ?? null,
          preMarketChangePercent:   mkt.preMarketChangePercent   ?? null,
          postMarketPrice:          mkt.postMarketPrice          ?? null,
          postMarketChangePercent:  mkt.postMarketChangePercent  ?? null
        };
      }
    }

    if (pplx?.analystActions?.length) {
      const ptMentioned = pplx.analystActions.some(a => item.summary?.includes(a.bank) || item.summary?.includes('$' + a.target));
      if (!ptMentioned) {
        item.alerts = item.alerts || [];
        pplx.analystActions.forEach(a => {
          item.alerts.push({ type: 'critical', text: `${a.bank} price target $${a.target} — verify if recent` });
        });
      }
    }

    if (item.alerts?.length) {
      const seen = new Set();
      item.alerts = item.alerts.filter(a => { const key = (a.text||'').slice(0,50); if (seen.has(key)) return false; seen.add(key); return true; });
    }

    const chg = mkt?.change_percent ?? 0;
    if (typeof item.sentiment_score === 'number' && chg < -5 && item.sentiment_score > 60) { console.warn(`[PT] Orchestrate: score override ${sym} down ${chg}%`); item.sentiment_score = Math.min(item.sentiment_score, 45); item.sentiment = 'negative'; }
    if (typeof item.sentiment_score === 'number' && chg > 5  && item.sentiment_score < 40) { console.warn(`[PT] Orchestrate: score override ${sym} up ${chg}%`);   item.sentiment_score = Math.max(item.sentiment_score, 55); item.sentiment = 'positive'; }

    // Phase 6A-1: Technical setup clamp + audit trail
    const _snap6a    = (techSnaps && techSnaps[sym]) ? techSnaps[sym] : {};
    const _setup6a   = classifyTechnicalSetup(_snap6a);
    const _pplx6a    = pplxData?.[sym] || pplxData?.['__raw__'];
    // Normalize AI fields that may arrive as the string "null" instead of actual null
    ['conflict','entry_zone','invalidation','key_risk'].forEach(k => {
      if (typeof item[k] === 'string' && item[k].trim().toLowerCase() === 'null') item[k] = null;
    });
    // Issue 1: deterministic setup is source of truth — overwrite AI-generated technical_setup
    if (_setup6a && _setup6a !== 'unknown') item.technical_setup = _setup6a;
    else item.technical_setup = item.technical_setup || 'unknown';
    // Score clamp: extended_near_ath — use item.technical_setup (already overridden above) as reliable source
    if (item._aiUnavailable !== true && item.technical_setup === 'extended_near_ath' && item.sentiment_score > 62) {
      console.warn(`[PT] Orchestrate: setup clamp ${sym} extended_near_ath → score ${item.sentiment_score} → 62`);
      item.sentiment_score = 62;
    }
    // Issue 2a: extended_near_ath — gate action, conflict, key_risk
    if (item._aiUnavailable !== true && _setup6a === 'extended_near_ath') {
      if (!item.action || item.action.startsWith('add_') || item.action === 'buy') {
        console.warn(`[PT] Orchestrate: action override ${sym} extended_near_ath → hold_wait (was: ${item.action})`);
        item.action = 'hold_wait';
      }
      if (!item.key_risk) item.key_risk = 'Chasing an extended move near highs.';
      if (!item.conflict && (item.news_bias === 'bullish' || item.news_bias === 'positive' || item.sentiment === 'positive')) {
        item.conflict = 'Bullish catalyst, but price is extended near highs; wait for pullback or consolidation.';
      }
    }
    // Score clamp: below_key_mas
    if (item._aiUnavailable !== true && _setup6a === 'below_key_mas' && item.sentiment_score > 45) {
      console.warn(`[PT] Orchestrate: setup clamp ${sym} below_key_mas → score ${item.sentiment_score} → 45`);
      item.sentiment_score = 45;
      item.sentiment = 'negative';
    }
    // Issue 2b: below_key_mas — gate action, sentiment, key_risk, conflict
    if (item._aiUnavailable !== true && _setup6a === 'below_key_mas') {
      if (item.action !== 'avoid') {
        console.warn(`[PT] Orchestrate: action override ${sym} below_key_mas → avoid (was: ${item.action})`);
        item.action = 'avoid';
      }
      item.sentiment = 'negative';
      if (!item.key_risk) item.key_risk = 'Price is below key moving averages; trend risk remains elevated.';
      if (!item.conflict && (item.news_bias === 'bullish' || item.news_bias === 'positive')) {
        item.conflict = 'Bullish catalyst conflicts with weak technical structure below key moving averages.';
      }
    }
    // Attach structured audit trail — console + object level only in 6A-1
    // (assembled after all overrides so finalDecision reflects corrected values)
    // 6B-1: per-item flag so render layer can pick the right catalyst fallback wording
    item._catalystDataMissing = !!(_pplx6a && (_pplx6a._allNone || _pplx6a._unavailable));
    // 6B-2: derive catalyst-existence + direction signals for the catalyst panel
    // _catalystDataMissing (6B-1) retains priority — checked first in the render ternary
    const _bullPplx       = _pplx6a?.bullishCatalysts?.length || 0;
    const _bearPplx       = _pplx6a?.bearishCatalysts?.length || 0;
    const _hasClaudeNews  = Array.isArray(item.news) && item.news.length > 0;
    const _biasDirectional = (item.news_bias === 'bullish' || item.news_bias === 'bearish');
    item._hasStructuredCatalysts = (_bullPplx > 0 || _bearPplx > 0 || _hasClaudeNews || _biasDirectional);
    item._catalystDirection = null;
    if (item._hasStructuredCatalysts) {
      if      (item.news_bias === 'bullish')      item._catalystDirection = 'bullish';
      else if (item.news_bias === 'bearish')      item._catalystDirection = 'bearish';
      else if (_bullPplx > 0 && _bearPplx === 0)  item._catalystDirection = 'bullish';
      else if (_bearPplx > 0 && _bullPplx === 0)  item._catalystDirection = 'bearish';
      else                                         item._catalystDirection = 'mixed';
    }
    // 7B-2A: pass-through structured catalyst payload from pplxData so the render layer
    // (next commit) can read real catalyst data from pt_results without depending on the
    // per-batch _lastRunState that is overwritten and lost on reload. Additive only —
    // no renderer consumes this field yet. Old persisted results without _catalysts
    // remain safe because nothing reads it in this commit.
    item._catalysts = {
      bullish:         _pplx6a?.bullishCatalysts  || [],
      bearish:         _pplx6a?.bearishCatalysts  || [],
      macro:           _pplx6a?.macroDrivers      || [],
      analystActions:  _pplx6a?.analystActions    || [],
      earnings:        _pplx6a?.earnings          || null,
      sources:         _pplx6a?.sources           || [],
      freshness:       _pplx6a?.dataFreshness     || null,
      revisionDir:     _pplx6a?.revisionDirection || null,
      revisionRecency: _pplx6a?.revisionRecency   || null
    };
    // 7B-3D0: enrich the per-ticker memory-only debug snapshot with orchestrated/result
    // fields and the formatNewsContext output (what Anthropic actually sees). NEVER persisted.
    if (window._pplxDebug && window._pplxDebug[sym]) {
      try {
        window._pplxDebug[sym].resultCatalysts        = JSON.parse(JSON.stringify(item._catalysts));
        window._pplxDebug[sym].catalystDataMissing    = item._catalystDataMissing;
        window._pplxDebug[sym].hasStructuredCatalysts = item._hasStructuredCatalysts;
        window._pplxDebug[sym].catalystDirection      = item._catalystDirection;
        window._pplxDebug[sym].newsBias               = item.news_bias || null;
        window._pplxDebug[sym].actionableAction       = item.action    || null;
        window._pplxDebug[sym].formattedNewsContext   = (typeof formatNewsContext === 'function') ? formatNewsContext(pplxData, sym) : null;
      } catch (_e) { /* debug-only; never break the run */ }
    }
    // 6B-3: Key Risk / Catalyst Contradiction Guard
    // When structured bullish catalysts exist but Claude's key_risk denies catalyst existence,
    // replace with a setup-aware deterministic fallback. Bearish/mixed/missing left untouched.
    if (item._hasStructuredCatalysts &&
        item._catalystDirection === 'bullish' &&
        item._catalystDataMissing !== true &&
        typeof item.key_risk === 'string' &&
        /\b(no\s+(?:(?:verified|fundamental|identified)\s+){1,3}catalyst|lack\s+of\s+catalyst|absence\s+of\s+catalyst|missing\s+catalyst|without\s+catalyst)/i.test(item.key_risk)) {
      const _krBefore = item.key_risk;
      const _krFallback =
        item.technical_setup === 'extended_near_ath' ? 'Chasing an extended move near highs.' :
        item.technical_setup === 'below_key_mas'     ? 'Price is below key moving averages; trend risk remains elevated.' :
                                                       'Follow-through risk despite confirmed catalysts.';
      console.warn(`[PT] Orchestrate: key_risk catalyst-contradiction guard ${sym} → "${_krFallback}" (was: "${_krBefore}")`);
      item.key_risk = _krFallback;
    }
    item._auditTrail = {
      dataCollected: {
        price:         mkt?.price          ?? null,
        dayChange:     mkt?.change_percent ?? null,
        ma20:          _snap6a.sma20       ?? null,
        ma50:          _snap6a.sma50       ?? null,
        ma150:         _snap6a.sma150      ?? null,
        pctAboveMA20:  _snap6a.pct20       ?? null,
        pctAboveMA50:  _snap6a.pct50       ?? null,
        pctAboveMA150: _snap6a.pct150      ?? null,
        high1yDist:    _snap6a.high1yDist  ?? null,
        rsSPY:         _snap6a.rsSPY       ?? null,
        rsQQQ:         _snap6a.rsQQQ       ?? null,
        rsSector:      _snap6a.rsSector    ?? null,
        volRatio:      _snap6a.volRatio    ?? null,
        catalysts:     _pplx6a?.bullishCatalysts ?? []
      },
      sourceTrace: {
        marketData:        mkt?.source || 'unknown',
        historicalCandles: 'market-data / yahoo-proxy / polygon / av-proxy (1Y)',
        technicalFunction: 'computeTechnicalSnapshot()',
        // 6B-1: tri-state Perplexity source label
        newsContext:       _pplx6a?._unavailable
                             ? 'perplexity-proxy / unavailable'
                             : _pplx6a?._allNone
                               ? 'perplexity-proxy / no catalyst data'
                               : 'perplexity-proxy / sonar-pro',
        aiSynthesis:       'anthropic-proxy / claude-haiku-4-5-20251001'
      },
      interpretation: {
        technicalSetup: _setup6a,
        newsBias:       item.news_bias  || null,
        conflict:       item.conflict   || null
      },
      finalDecision: {
        action:       item.action       || null,
        entryZone:    item.entry_zone   || null,
        invalidation: item.invalidation || null,
        keyRisk:      item.key_risk     || null
      }
    };
    console.log(`[PT] auditTrail ${sym}:`, JSON.stringify(item._auditTrail));
    // 7B-3D0: attach sourceTrace into the memory-only debug snapshot (auditTrail now ready)
    if (window._pplxDebug && window._pplxDebug[sym] && item._auditTrail) {
      window._pplxDebug[sym].sourceTrace = item._auditTrail.sourceTrace || null;
    }
    item._orchestrated = true;
    item._orchestratedAt = new Date().toISOString();
    return item;
  });
}

renderMainPanel.source:
function renderMainPanel(item) {
  const panel = document.getElementById('mainPanel');
  if (!panel) return;

  const score = _ptScoreNorm(item.sentiment_score); // null = missing (never 50, never 0)
  const sent  = item.sentiment==='positive'?'positive':item.sentiment==='negative'?'negative':'neutral';
  let chg   = typeof item._verifiedChangePct==='number' ? item._verifiedChangePct : null;
  let price = item._verifiedPrice ? `$${item._verifiedPrice.toFixed(2)}` : '—';
  const sum   = item.summary || '';
  const sl    = sum.toLowerCase();

  const getS = tag => {
    const m = sum.match(new RegExp(tag+':?\\s*(.+?)(?=KEY EVENT:|ROOT CAUSE:|PRICE CONTEXT:|BULL VS BEAR:|ACTIONABLE TAKE:|Rating:|$)','si'));
    return m ? m[1].trim().replace(/\n/g,' ').replace(/\s+/g,' ') : '';
  };
  const actionable = getS('ACTIONABLE TAKE');
  const keyEvent   = getS('KEY EVENT');

  const rM = sum.match(RATING_SUMMARY_RE);
  const pM = sum.match(/PT:\s*\$?([\d,.]+|consensus unavailable)/i);
  const rating = rM ? rM[1] : null; // R-5 (Entry 37): no silent "Neutral" fallback
  const pt     = pM&&pM[1]!=='consensus unavailable'?'$'+pM[1]:'—';
  const _pulseBand = score === null ? 'neutral-v' : score >= 65 ? 'pos' : score <= 40 ? 'neg' : 'neutral-v'; // R-5 (Entry 37, ruling A1): the Pulse score band colours the dial and the chip

  // Data-quality flag — gates all derived technical/RS/volume metrics
  const hasData    = hasVerifiedMarketData(item);
  const _mktFailed = _mktFailCache[item.ticker] === true; // display-only; never read by scoring

  // Setup grade — removed from header in Phase 2b; kept as dead vars to avoid refactor
  // of lower body panels that may still reference sc/sg (safe: not rendered in header)
  const hasCrit = (item.alerts||[]).some(a=>a.type==='critical');

  // Timeframe Alignment — deterministic map from technical_setup (Phase 6A-3)
