      <div id="ffp-card" class="pc-card pc-span-12${_ffpCardCollapsed ? ' collapsed' : ''}">
        <div class="pc-card-title" onclick="_ffpToggleCard()">Fundamentals Factors (non-scoring) <span class="ffp-chevron">${_ffpCardCollapsed ? '▶' : '▼'}</span></div>
        <div class="pc-card-sub" style="margin-top:0">Display-only · projected from the loaded Fund Facts envelope · verify independently</div>
        <div id="ffp-panel-${item.ticker}"></div>
      </div>` : ''}

    </div>

    <div class="src-trace">
      <span class="src-trace-hdr">SOURCE TRACE</span>
      <div class="src-trace-chips">
        <span class="src-trace-chip">Price: <span class="src-trace-val neutral-v">${item._dataSource === 'alphavantage' ? 'av-proxy' : item._dataSource || '—'}</span></span>
        <span class="src-trace-sep">·</span>
        <span class="src-trace-chip">Candles: <span class="src-trace-val neutral-v">${!hasData ? '—' : snap.candleCount === undefined ? 'loading…' : snap.candleCount > 0 ? snap.candleCount + ' bars' : '—'}</span></span>
        <span class="src-trace-sep">·</span>
        <span class="src-trace-chip">MA / RS: <span class="src-trace-val ${!hasData || snap.candleCount === undefined ? 'neutral-v' : snap.hasMA20 && snap.rsSPY !== null ? 'pos' : snap.hasMA20 ? 'warn' : 'neg'}">${!hasData || snap.candleCount === undefined ? '—' : snap.hasMA20 && snap.rsSPY !== null ? 'computed' : snap.hasMA20 ? 'MA only' : 'unavailable'}</span></span>
        <span class="src-trace-sep">·</span>
        <span class="src-trace-chip">News: <span class="src-trace-val ${item._catalystDataMissing ? 'warn' : 'neutral-v'}">${item._auditTrail?.sourceTrace?.newsContext ? item._auditTrail.sourceTrace.newsContext.replace('perplexity-proxy / ', 'Perplexity / ') : '—'}</span></span>
        <span class="src-trace-sep">·</span>
        <span class="src-trace-chip">AI: <span class="src-trace-val ${item._aiUnavailable ? 'neg' : 'neutral-v'}">${item._aiUnavailable ? 'unavailable' : (item._auditTrail?.sourceTrace?.aiSynthesis || '—').replace('anthropic-proxy / ', '').replace('claude-haiku-4-5-20251001', 'claude-haiku-4-5')}</span></span>
        <span class="src-trace-sep">·</span>
        <span class="src-trace-chip">Updated: <span class="src-trace-val neutral-v">${(() => { const t = item._orchestratedAt || item._timestamp; if (!t) return '—'; try { const d = new Date(t); const n = new Date(); const same = d.getFullYear()===n.getFullYear()&&d.getMonth()===n.getMonth()&&d.getDate()===n.getDate(); return same ? d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}) : d.toLocaleDateString('en-US',{month:'short',day:'numeric'})+' · '+d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}); } catch(e) { return '—'; } })()}</span></span>
      </div>
    </div>
${window.PT_ENABLE_EDGAR_FORM4 === true ? `
    <div class="mp-dd-bar" id="edgar-dd-bar-${item.ticker}">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:12px">
        <span style="font-family:var(--mono);font-size:8px;font-weight:600;text-transform:uppercase;letter-spacing:1px;color:var(--text3)">Insider / Form 4 — SEC EDGAR</span>
        <button class="mp-dd-btn" id="edgar-dd-btn-${item.ticker}"
          onclick="_runEdgarInsiderDeepDive('${item.ticker}')">▶ Check Insider Activity</button>
      </div>
      <div id="edgar-dd-panel-${item.ticker}" style="display:none;margin-top:10px"></div>
    </div>` : ''}
${window.PT_ENABLE_DEEP_DIVE === true ? `
    <div id="dd0-card" class="pc-card${_dd0CardCollapsed ? ' collapsed' : ''}">
      <div class="pc-card-title">Deep Dive — AI Analysis <span class="ts-chevron">${_dd0CardCollapsed ? '▶' : '▼'}</span></div>
    <div class="mp-dd-bar" id="dd0-bar-${item.ticker}">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:12px">
        <span style="font-family:var(--mono);font-size:8px;font-weight:600;text-transform:uppercase;letter-spacing:1px;color:var(--text3)">Deep Dive — AI Analysis</span>
        <button class="mp-dd-btn" id="dd0-btn-${item.ticker}"
          onclick="_dd0RunCard('${item.ticker}')">▶ Run Deep Dive</button>
      </div>
      <div id="dd0-panel-${item.ticker}" style="display:none;margin-top:10px"></div>
    </div>
    </div>` : ''}
  `; /* DDV0-IMPL: Deep Dive v0 client trigger, gated by PT_ENABLE_DEEP_DIVE, rendered above */
  _initTsCard();
  _initSigCard();
  _initCmpCard();
  _initKlCard();
  _initDd0Card();
  _ts1FillRow(item.ticker); // backlog task 6: async post-render fill of the gated row (no-op when the gate is off)
}

_renderPortfolioPanel.source:
function _renderPortfolioPanel() {
  var panel = document.getElementById('portfolioPanel');
  if (!panel) return;
  var holdings = loadHoldings();
  var count    = Object.keys(holdings).length;
  if (_pfLiveRunCanceller) _pfLiveAbortActiveRun('superseded');
  panel.innerHTML = '';

  var hdr = document.createElement('div');
  hdr.className = 'pf-panel-hdr';

  var hdrLeft = document.createElement('div');
  var title   = document.createElement('div');
  title.className   = 'pf-panel-title';
  title.textContent = 'Portfolio';
  var countEl = document.createElement('div');
  countEl.className   = 'pf-panel-count';
  countEl.textContent = count === 0 ? 'No positions' : count + (count === 1 ? ' position' : ' positions');
  hdrLeft.appendChild(title);
  hdrLeft.appendChild(countEl);

  var hdrRight = document.createElement('div');
  hdrRight.style.cssText = 'display:flex;align-items:center;gap:6px;flex-shrink:0';

  var backupBtn = document.createElement('button');
  backupBtn.className   = 'btn-export';
  backupBtn.textContent = 'BACKUP ↓';
  backupBtn.title       = 'Export holdings + watchlist backup';
  backupBtn.onclick     = exportPortfolioBackup;

  var restoreBtn = document.createElement('button');
  restoreBtn.className   = 'btn-export';
  restoreBtn.textContent = 'RESTORE ↑';
  restoreBtn.title       = 'Import holdings + watchlist from backup file';
  restoreBtn.onclick     = function() {
    var inp = document.getElementById('pfImportInput');
    if (inp) { inp.value = ''; inp.click(); }
  };

  var eodExportBtn = document.createElement('button');
  eodExportBtn.className   = 'btn-export';
  eodExportBtn.textContent = 'EOD PACKET ↓';
  eodExportBtn.title       = 'Export end-of-day portfolio intelligence packet (JSON + Markdown)';
  eodExportBtn.onclick     = _eodExportPacket;

  var addBtn = document.createElement('button');
  addBtn.className   = 'btn-add-position';
  addBtn.textContent = '＋ Add Position';
  addBtn.onclick     = openAddPositionModal;

  // EG-19B-2/4: gated cloud buttons — SAVE left of LOAD, both left of BACKUP. Strict client gate;
  // off (default / on reload) means no buttons, no modals, no network.
  if (window.PT_ENABLE_PORTFOLIO_SYNC_CLIENT === true) {
    var saveCloudBtn = document.createElement('button');
    saveCloudBtn.className   = 'btn-export';
    saveCloudBtn.textContent = 'SAVE TO CLOUD ☁︎↑';
    saveCloudBtn.title       = 'Validate local data and push to cloud; overwrites the cloud copy entirely';
    saveCloudBtn.onclick     = openSaveToCloudModal;
    hdrRight.appendChild(saveCloudBtn);
    var cloudBtn = document.createElement('button');
    cloudBtn.className   = 'btn-export';
    cloudBtn.textContent = 'LOAD FROM CLOUD ☁︎↓';
    cloudBtn.title       = 'Fetch cloud holdings + watchlist for preview; applying overwrites local data after backup';
    cloudBtn.onclick     = openLoadFromCloudModal;
    hdrRight.appendChild(cloudBtn);
  }

  // P-2A/P-2B: manual refresh — always fetches (bypasses the automatic
  // cooldown). Shown when either the live-price or FX gate is on; each half
  // of the click handler independently checks its own gate (mirroring how
  // _pfEodManualRefresh/_pfFxManualRefresh already self-gate) so a portfolio
  // with only one of the two features enabled never fires the other's call.
  if ((window.PT_ENABLE_PORTFOLIO_LIVE_PRICES === true || window.PT_ENABLE_PORTFOLIO_FX === true) && count > 0) {
    var refreshBtn = document.createElement('button');
    refreshBtn.className   = 'btn-export';
    refreshBtn.textContent = 'REFRESH ⟳';
    refreshBtn.title       = 'Fetch latest completed-session prices / FX rate now';
    refreshBtn.onclick     = function() {
      if (window.PT_ENABLE_PORTFOLIO_LIVE_PRICES === true) _pfEodManualRefresh(Object.keys(loadHoldings()));
      if (window.PT_ENABLE_PORTFOLIO_FX === true) _pfFxManualRefresh();
    };
    hdrRight.appendChild(refreshBtn);
  }

  hdrRight.appendChild(backupBtn);
  hdrRight.appendChild(restoreBtn);
  hdrRight.appendChild(eodExportBtn);
  hdrRight.appendChild(addBtn);

  hdr.appendChild(hdrLeft);
  hdr.appendChild(hdrRight);
  panel.appendChild(hdr);

  // Root corruption gets its own branch, never the empty state below — a
  // corrupted-but-possibly-non-empty pt_holdings must never present as
  // "No positions yet. Add your first holding." (loadHoldings() already
  // refused to guess at the contents; saveHoldings() already refuses to
  // write until this clears). RESTORE ↑ is the only recovery path that
  // still works here — it writes independently of this flag.
  if (_pfRootCorrupted) {
    var corruptBlock = document.createElement('div');
    corruptBlock.className = 'pf-empty';
    var cIcon = document.createElement('div');
    cIcon.className   = 'pf-empty-icon';
    cIcon.textContent = '⚠';
    cIcon.style.color = 'var(--red2)';
    var cTxt = document.createElement('div');
    cTxt.className   = 'pf-empty-text';
    cTxt.style.color = 'var(--red2)';
    cTxt.textContent = 'Your saved portfolio data could not be read on this page load. Nothing was deleted, and saving is blocked until this is resolved. Use RESTORE ↑ to load a backup, or reload the page if this was temporary.';
    corruptBlock.appendChild(cIcon);
    corruptBlock.appendChild(cTxt);
    panel.appendChild(corruptBlock);
    return;
  }

  if (count === 0) {
    var empty = document.createElement('div');
    empty.className = 'pf-empty';
    var icon = document.createElement('div');
    icon.className   = 'pf-empty-icon';
    icon.textContent = '○';
    var txt = document.createElement('div');
    txt.className   = 'pf-empty-text';
    txt.textContent = 'No positions yet. Add your first holding.';
    empty.appendChild(icon);
    empty.appendChild(txt);
    panel.appendChild(empty);
  } else {
    var PF_CURRENCY_SYMBOLS = { USD: '$', ILS: '₪' };
    function _pfFmtCurrencyValue(v, currency) {
      var n = Number(v);
      if (!isFinite(n) || n <= 0) return '—';
      var formatted = n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      var sym = PF_CURRENCY_SYMBOLS[currency];
      return sym ? (sym + formatted) : formatted;
    }

    // Per-currency subtotals only — USD and ILS are not summed together (no
    // FX rate exists yet in P-1). A currency-unknown or _issues-flagged-
    // currency legacy holding is counted but never summed into a value,
    // since an unlabeled amount cannot honestly be added to anything. A
    // metadata-only issue (e.g. on manualPlPct/source/updatedAt) does NOT
    // exclude an entry here — only an invalid/missing positionSize or
    // currency does, since those are the two fields this total depends on.
    var _pfSub = _pfComputeHoldingsSubtotals(holdings);
    var usdSubtotal = _pfSub.usdSubtotal, ilsSubtotal = _pfSub.ilsSubtotal,
        unknownCurrencyCount = _pfSub.unknownCurrencyCount,
        hasCorrupt = _pfSub.hasCorrupt, corruptCount = _pfSub.corruptCount;

    // Two distinct categories, surfaced with distinct wording: _corrupt/
    // _issues means something couldn't be read correctly (a real problem);
    // _legacyFields-only means the holding has additional fields this
    // version doesn't interpret, which may be perfectly valid data — never
    // described as "could not be read".
    var brokenSymbols = Object.keys(holdings).filter(function(k) {
      var h = holdings[k];
      return h._corrupt === true || (h._issues && h._issues.length > 0);
    });
    var legacyFieldSymbols = Object.keys(holdings).filter(function(k) {
      var h = holdings[k];
      return !brokenSymbols.includes(k) && h._legacyFields && Object.keys(h._legacyFields).length > 0;
    });
    if (brokenSymbols.length > 0) {
      var flagBanner = document.createElement('div');
      flagBanner.className   = 'pf-guidance';
      flagBanner.style.color = 'var(--red2)';
      flagBanner.textContent = brokenSymbols.length + ' holding' + (brokenSymbols.length === 1 ? '' : 's') +
        ' could not be fully read and need attention (' + brokenSymbols.join(', ') + '). Nothing was deleted — open Edit on each to repair.';
      panel.appendChild(flagBanner);
    }
    if (legacyFieldSymbols.length > 0) {
      var legacyBanner = document.createElement('div');
      legacyBanner.className   = 'pf-guidance';
      legacyBanner.style.color = 'var(--yellow2)';
      legacyBanner.textContent = legacyFieldSymbols.length + ' holding' + (legacyFieldSymbols.length === 1 ? '' : 's') +
        ' contain additional legacy field(s) not yet used by Pulse (' + legacyFieldSymbols.join(', ') + '). They are currently preserved and will not be interpreted by P-1.';
      panel.appendChild(legacyBanner);
    }

    var summary = document.createElement('div');
    summary.className = 'pf-summary';
    function _pfSummaryStat(label, valueText) {
      var s = document.createElement('div');
      s.className = 'pf-summary-stat';
      var l = document.createElement('div');
      l.className   = 'pf-summary-lbl';
      l.textContent = label;
      var v = document.createElement('div');
      v.className   = 'pf-summary-val';
      v.textContent = valueText;
      s.appendChild(l);
      s.appendChild(v);
      return s;
    }
    summary.appendChild(_pfSummaryStat('Positions', String(count)));
    if (usdSubtotal > 0) {
      summary.appendChild(_pfSummaryStat('USD Recorded Value', '$' + usdSubtotal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })));
    }
    if (ilsSubtotal > 0) {
      summary.appendChild(_pfSummaryStat('ILS Recorded Value', '₪' + ilsSubtotal.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })));
    }
    if (unknownCurrencyCount > 0) {
      summary.appendChild(_pfSummaryStat('Currency Not Recorded', String(unknownCurrencyCount) + (unknownCurrencyCount === 1 ? ' holding' : ' holdings')));
    }
    // ─── P-2B: Cash, FX, and the two-label Portfolio Total honesty model ───
    // All completeness/total/allocation-denominator math lives in
    // _pfComputePortfolioReporting (pure, shared with the offline QA suite)
    // — this block only turns its result into DOM. Missing cash/FX/gaps
    // never silently become zero; they flip the total's label from
    // "Portfolio Total" to "Known Assets Total" and are disclosed by name
    // rather than folded into a number that looks complete.
    var cashState  = _pfCashLoad();
    var fxCache    = _pfFxLoadCache();
    var reporting  = _pfComputePortfolioReporting(usdSubtotal, ilsSubtotal, unknownCurrencyCount, hasCorrupt, corruptCount, cashState, fxCache);
    var fxState    = reporting.fxState;
    var completeness = reporting.completeness;
    var completenessReasons = reporting.completenessReasons;

    // Cash line — always rendered regardless of any gate, three distinct
    // states, never coerced to a number when unset/invalid (see _pfCashLoad).
    // Allocation % (cash's own share of the complete portfolio) is appended
    // only when completeness is true — the approved model always includes
    // cash in the denominator, so cash needs the same owner-visible
    // allocation figure a holding card gets, not just its raw ₪ amount.
    var cashBlock = document.createElement('div');
    cashBlock.className = 'pf-summary-stat';
    var cashLbl = document.createElement('div');
    cashLbl.className   = 'pf-summary-lbl';
    cashLbl.textContent = 'Cash (ILS)';
    var cashVal = document.createElement('div');
    cashVal.className = 'pf-summary-val';
    if (cashState.state === 'recorded') {
      cashVal.textContent = '₪' + cashState.amountILS.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    } else if (cashState.state === 'invalid') {
      cashVal.textContent = '— (cash data invalid)';
      cashVal.style.color = 'var(--red2)';
    } else {
      cashVal.textContent = '— (not recorded)';
    }
    cashBlock.appendChild(cashLbl);
    cashBlock.appendChild(cashVal);
    if (completeness && reporting.allocationDenominatorValue > 0) {
      var cashAllocEl = document.createElement('div');
      cashAllocEl.className = 'pf-pos-alloc';
      cashAllocEl.textContent = (reporting.cashIlsForTotal / reporting.allocationDenominatorValue * 100).toFixed(1) + '% of portfolio';
      cashBlock.appendChild(cashAllocEl);
    }
    var cashActions = document.createElement('div');
    cashActions.style.cssText = 'display:flex;gap:6px;margin-top:4px';
    var cashEditBtn = document.createElement('button');
    cashEditBtn.className   = 'btn-pf-edit';
    cashEditBtn.textContent = 'Edit';
    cashEditBtn.onclick     = function(){ openEditCashModal(); };
    cashActions.appendChild(cashEditBtn);
    if (cashState.state === 'recorded') {
      var cashClearBtn = document.createElement('button');
      cashClearBtn.className   = 'btn-pf-delete';
      cashClearBtn.textContent = 'Clear';
      // Persistence failures are detected, not silently ignored — same rule
      // P-1 applies to saveHoldings(). showToast mirrors deletePosition's
      // own failure-reporting pattern for a direct (non-modal) panel action.
      cashClearBtn.onclick     = function() {
        if (!confirm('Clear recorded cash? This returns cash to "not recorded" — it will NOT be treated as zero.')) return;
        var clearResult = _pfCashClear();
        if (clearResult.ok !== true) {
          showToast('Clear failed — your browser storage is unavailable or full. Cash was NOT cleared.');
          return;
        }
        _renderPortfolioPanel();
      };
      cashActions.appendChild(cashClearBtn);
    }
    cashBlock.appendChild(cashActions);
    summary.appendChild(cashBlock);

    // FX status chip — always rendered, never gated. PT_ENABLE_PORTFOLIO_FX
    // only controls whether a fetch is ever attempted (_pfFxAutoFetchIfDue/
    // _pfFxManualRefresh) — with it off, or on but never yet successful,
    // this honestly shows "FX unavailable" rather than inventing a rate.
    var fxChip = document.createElement('div');
    fxChip.className = 'pf-summary-stat';
    var fxChipLbl = document.createElement('div');
    fxChipLbl.className   = 'pf-summary-lbl';
    fxChipLbl.textContent = 'FX (USD/ILS)';
    var fxChipVal = document.createElement('div');
    fxChipVal.className = 'pf-summary-val';
    if (fxState === 'missing') {
      fxChipVal.textContent = DH_DISPLAY.surface['fx-not-fetched'];
    } else {
      var fxDateStr = new Date(fxCache.effectiveAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      // P-4A-1 FX-chip precision rider: the old 2dp display (3.01) rounded
      // far enough from the actual stored/used rate (3.006) to mis-reconcile
      // a real MRNA position by +₪19.90 vs the ₪10.85 the calculation
      // actually produces. 4dp plus a full-value tooltip so a manual
      // hand-reconciliation against this chip matches the math exactly — no
      // change to the rate itself or how it's persisted/used in formulas.
      var fxLabel = fxCache.rate.toFixed(4) + ' · ' + fxDateStr + ' · ' + String(fxCache.source || 'boi').toUpperCase();
      if (fxState === 'fresh') {
        fxChipVal.textContent = 'FX ' + fxLabel;
      } else if (fxState === 'aged-but-valid') {
        fxChipVal.textContent = 'FX ' + fxLabel + ' — ' + _dhFxAgedLabel(_pfFxAgeWholeDays(fxCache));
        fxChipVal.style.color = 'var(--yellow2)';
      } else {
        fxChipVal.textContent = 'FX ' + fxLabel + ' — ' + _dhLabel('state', 'stale-invalid') + ', not used in totals';
        fxChipVal.style.color = 'var(--yellow2)';
      }
      fxChipVal.title = 'Exact rate used in calculations: ' + fxCache.rate;
    }
    fxChip.appendChild(fxChipLbl);
    fxChip.appendChild(fxChipVal);
    summary.appendChild(fxChip);

    // Portfolio Total (ILS) — two-label honesty model, value/completeness
    // already computed by _pfComputePortfolioReporting above. "Portfolio
    // Total" claims completeness; "Known Assets Total" never does, and
    // always discloses exactly what it excludes (completenessReasons). An
    // aged-but-valid FX rate is good enough for this total (amber-qualified)
    // but not for the stricter day-estimate below.
    if (completeness) {
      var totalValText = '₪' + reporting.total.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      var totalStat = _pfSummaryStat('Portfolio Total (ILS)', totalValText);
      if (fxState === 'aged-but-valid') {
        var totalQualifier = document.createElement('div');
        totalQualifier.style.cssText = 'font-size:10px;color:var(--yellow2);margin-top:2px';
        totalQualifier.textContent = 'FX as of ' + new Date(fxCache.effectiveAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' — ' + _dhFxAgedLabel(_pfFxAgeWholeDays(fxCache));
        totalStat.appendChild(totalQualifier);
      }
      summary.appendChild(totalStat);
    } else {
      var knownValText = reporting.knownHasComponent
        ? ('₪' + reporting.total.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }))
        : '—';
      var knownStat = _pfSummaryStat('Known Assets Total (ILS)', knownValText);
      var knownDetail = document.createElement('div');
      knownDetail.style.cssText = 'font-size:10px;color:var(--text3);margin-top:2px';
      knownDetail.textContent = 'Excludes: ' + completenessReasons.join(' · ');
      knownStat.appendChild(knownDetail);
      summary.appendChild(knownStat);
    }

    // ─── P-4A-1: Broker reconciliation ───────────────────────────────────────
    // Deliberately separate from P-2B's completeness/Portfolio-Total model
    // above — "complete" (no known component missing) and "reconciled"
    // (matches the broker) are two distinct claims, kept visually and
    // semantically apart. _pfComputeReconciliation owns the entire state
    // machine (unset/invalid/stale/total-incomplete/fully-reconciled/
    // reconciled-with-exclusions/unexplained-gap); this block only turns its
    // result into DOM.
    var reconState = _pfReconLoad();
    var reconOldestBaselineAt = _pfReconOldestBaselineAt(holdings);
    var recon = _pfComputeReconciliation(reconState, reporting.total, completeness, reconOldestBaselineAt);

    var reconStat = document.createElement('div');
    reconStat.className = 'pf-summary-stat';
    var reconLbl = document.createElement('div');
    reconLbl.className   = 'pf-summary-lbl';
    reconLbl.textContent = 'Broker Reconciliation';
    var reconVal = document.createElement('div');
    reconVal.className = 'pf-summary-val';

    if (recon.status === 'unset') {
      reconVal.textContent = 'Broker total — ' + _dhLabel('state', 'unset');
    } else if (recon.status === 'invalid') {
      reconVal.textContent = 'Broker total — ' + _dhLabel('state', 'invalid');
      reconVal.style.color = 'var(--red2)';
    } else if (recon.status === 'stale') {
      reconVal.textContent = 'Broker total — ' + _dhLabel('state', 'stale');
      reconVal.style.color = 'var(--yellow2)';
    } else if (recon.status === 'total-incomplete') {
      reconVal.textContent = 'Reconciliation — ' + _dhLabel('state', 'total-incomplete');
      reconVal.style.color = 'var(--text3)';
    } else if (recon.status === 'fully-reconciled') {
      reconVal.textContent = 'Reconciled · as of ' + new Date(reconState.asOf).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      reconVal.style.color = 'var(--green2)';
    } else if (recon.status === 'reconciled-with-exclusions') {
      reconVal.textContent = 'Reconciled · ₪' + recon.exclusions.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) +
        ' declared exclusions · as of ' + new Date(reconState.asOf).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      reconVal.style.color = 'var(--green2)';
      if (reconState.exclusionsNote) reconVal.title = reconState.exclusionsNote;
    } else if (recon.status === 'unexplained-gap') {
      reconVal.textContent = 'Unexplained ₪' + Math.abs(recon.unexplained).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) +
        ' — a holding may be missing from Pulse';
      reconVal.style.color = 'var(--yellow2)';
    }
    reconStat.appendChild(reconLbl);
    reconStat.appendChild(reconVal);

    if (recon.status === 'total-incomplete') {
      var reconIncompleteDetail = document.createElement('div');
      reconIncompleteDetail.style.cssText = 'font-size:10px;color:var(--text3);margin-top:2px';
      reconIncompleteDetail.textContent = 'Portfolio Total (ILS) is incomplete — see Known Assets Total above';
      reconStat.appendChild(reconIncompleteDetail);
    }
    if (recon.status === 'stale' && recon.staleDays !== null) {
      var reconStaleDetail = document.createElement('div');
      reconStaleDetail.style.cssText = 'font-size:10px;color:var(--text3);margin-top:2px';
      reconStaleDetail.textContent = Math.round(recon.staleDays) + ' day(s) between recorded as-of and oldest holding baseline (conservative heuristic)';
      reconStat.appendChild(reconStaleDetail);
    }

    var reconActions = document.createElement('div');
    reconActions.style.cssText = 'display:flex;gap:6px;margin-top:4px';
    var reconEditBtn = document.createElement('button');
    reconEditBtn.className   = 'btn-pf-edit';
    reconEditBtn.textContent = 'Edit';
    reconEditBtn.onclick     = function(){ openEditReconModal(); };
    reconActions.appendChild(reconEditBtn);
    if (reconState.state === 'recorded') {
      var reconClearBtn = document.createElement('button');
      reconClearBtn.className   = 'btn-pf-delete';
      reconClearBtn.textContent = 'Clear';
      // Persistence failures are detected, not silently ignored — same rule
      // the cash Clear button above follows.
      reconClearBtn.onclick     = function() {
        if (!confirm('Clear recorded broker reconciliation? This returns it to "not recorded" — it will NOT be treated as reconciled or as a gap.')) return;
        var clearResult = _pfReconClear();
        if (clearResult.ok !== true) {
          showToast('Clear failed — your browser storage is unavailable or full. Reconciliation was NOT cleared.');
          return;
        }
        _renderPortfolioPanel();
      };
      reconActions.appendChild(reconClearBtn);
    }
    reconStat.appendChild(reconActions);
    summary.appendChild(reconStat);

    // Portfolio-level day estimate — see _pfPortfolioDayEstimate: strictly
    // fresh-FX-only for USD holdings (stricter than the total's bar above),
    // all-covered-fresh-or-suppress, never presented as full-portfolio when
    // any holding was excluded from the covered set.
    var dayEst = _pfPortfolioDayEstimate(holdings);
    if (dayEst !== null) {
      var estSign = dayEst.totalIls > 0 ? '+' : (dayEst.totalIls < 0 ? '-' : '');
      var estLabel = 'Est. Daily Move' + (dayEst.partial ? ' (covered holdings only)' : '');
      var estValText = estSign + '₪' + Math.abs(dayEst.totalIls).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      var estStat = _pfSummaryStat(estLabel, estValText);
      var estValEl = estStat.querySelector('.pf-summary-val');
      if (estValEl) estValEl.style.color = dayEst.totalIls > 0 ? 'var(--green2)' : dayEst.totalIls < 0 ? 'var(--red2)' : '';
      summary.appendChild(estStat);
    }

    // ─── P-3: Unrealized P/L (ILS) — cost-basis-based money math ────────────
    // Pure aggregation lives entirely in _pfComputePortfolioPl; this block
    // only turns its result into DOM. Cash is never included (no cost
    // basis — stays part of P-2B's separate Portfolio Total above). Shown
    // only once at least one holding is eligible; an all-empty portfolio
    // (no cost basis entered yet anywhere) shows nothing here rather than a
    // permanent, meaningless "—" stat. Both stats carry their own "Covers N
    // of M holdings" disclosure when incomplete — the return % is exactly as
    // partial as the P/L money figure it's derived from, and must never
    // read as a full-portfolio return when it isn't one.
    var pfPl = _pfComputePortfolioPl(holdings, fxCache);
    if (pfPl.coveredCount > 0) {
      var pfPlCoverageText = 'Covers ' + pfPl.coveredCount + ' of ' + pfPl.totalCount + ' holdings';

      var pfPlValText = (pfPl.totalPlIls >= 0 ? '+' : '-') + '₪' + Math.abs(pfPl.totalPlIls).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      var pfPlStat = _pfSummaryStat('Unrealized P/L (ILS)', pfPlValText);
      var pfPlValEl = pfPlStat.querySelector('.pf-summary-val');
      if (pfPlValEl) pfPlValEl.style.color = pfPl.totalPlIls > 0 ? 'var(--green2)' : pfPl.totalPlIls < 0 ? 'var(--red2)' : '';
      if (!pfPl.complete) {
        var pfPlDetail = document.createElement('div');
        pfPlDetail.style.cssText = 'font-size:10px;color:var(--text3);margin-top:2px';
        pfPlDetail.textContent = pfPlCoverageText;
        pfPlStat.appendChild(pfPlDetail);
      }
      summary.appendChild(pfPlStat);

      var pfRetLabel = 'Unrealized return (ILS)' + (pfPl.complete ? '' : ' (covered holdings only)');
      var pfRetValText = (pfPl.returnPctIls >= 0 ? '+' : '') + pfPl.returnPctIls.toFixed(2) + '%';
      var pfRetStat = _pfSummaryStat(pfRetLabel, pfRetValText);
      var pfRetValEl = pfRetStat.querySelector('.pf-summary-val');
      if (pfRetValEl) pfRetValEl.style.color = pfPl.returnPctIls > 0 ? 'var(--green2)' : pfPl.returnPctIls < 0 ? 'var(--red2)' : '';
      if (!pfPl.complete) {
        var pfRetDetail = document.createElement('div');
        pfRetDetail.style.cssText = 'font-size:10px;color:var(--text3);margin-top:2px';
        pfRetDetail.textContent = pfPlCoverageText;
        pfRetStat.appendChild(pfRetDetail);
      }
      summary.appendChild(pfRetStat);
    }
    panel.appendChild(summary);

    if (pfPl.coveredCount > 0) {
      var pfPlNote = document.createElement('div');
      pfPlNote.className   = 'pf-guidance';
      pfPlNote.textContent = 'Unrealized, current holdings only — realized gains from past exits not included.';
      panel.appendChild(pfPlNote);
    }

    // ─── P-4A-2: Needs Attention ──────────────────────────────────────
    // Read-only aggregation of signals already computed above/elsewhere in
    // this render pass (holdings, fxCache, cashState, recon) via
    // _pfComputeNeedsAttention. See that function for dedup rules and
    // ordering; this block only turns its already-sorted result into DOM,
    // preserving the returned order exactly. Colors follow existing
    // precedent: red for records that could not be read at all (corrupt
    // holdings, invalid reconciliation data — same red used by the broken-
    // holdings banner above and the recon "invalid" state); amber for every
    // other item (a review/verify signal, not a hard error — same amber the
    // Broker Reconciliation stat already uses for its own unexplained-gap
    // state). Critical-tier items additionally get a bordered badge (inline
    // style, no new CSS class) so they read as visually stronger than
    // High/Medium/Low, which stay plain colored text.
    var attentionItems = _pfComputeNeedsAttention(holdings, fxCache, recon, cashState);
    if (attentionItems.length > 0) {
      var attentionBlock = document.createElement('div');
      attentionBlock.className = 'pf-attention';
      var attentionHdr = document.createElement('div');
      attentionHdr.className   = 'pf-attention-hdr';
      attentionHdr.textContent = 'Needs Attention (' + attentionItems.length + ')';
      attentionBlock.appendChild(attentionHdr);
      attentionItems.forEach(function(item) {
        var row = document.createElement('div');
        row.className = 'pf-attention-item';
        var isRed = (item.id === 'corrupt:aggregate' || item.id === 'recon:invalid');
        var color = isRed ? 'var(--red2)' : 'var(--yellow2)';
        var title = document.createElement('div');
        title.className   = 'pf-attention-title';
        title.style.color = color;
        title.textContent = '⚠ ' + item.title;
        if (item.severity === 'critical') {
          title.style.display      = 'inline-block';
          title.style.border       = '1px solid ' + color;
          title.style.borderRadius = '3px';
          title.style.padding      = '2px 7px';
          title.style.fontWeight   = '700';
        }
        row.appendChild(title);
        var detail = document.createElement('div');
        detail.className   = 'pf-attention-detail';
        detail.textContent = item.detail;
        row.appendChild(detail);
        attentionBlock.appendChild(row);
      });
      panel.appendChild(attentionBlock);
    }

    var agg = _calcPortfolioAggregates(holdings);
    var covRow = document.createElement('div');
    covRow.className = 'pf-coverage';
    function _mkCovStat(label, covered, total) {
      var s = document.createElement('div');
      s.className = 'pf-cov-stat';
      var l = document.createElement('div');
      l.className = 'pf-cov-lbl';
      l.textContent = label;
      var v = document.createElement('div');
      v.className = 'pf-cov-val';
      v.textContent = covered + ' / ' + total;
      s.appendChild(l);
      s.appendChild(v);
      return s;
    }
    covRow.appendChild(_mkCovStat('Manual P/L Coverage', agg.manualPl.covered, agg.manualPl.total));
    if (agg.research !== null) {
      var resStat = _mkCovStat('Research Coverage', agg.research.covered, agg.research.total);
      // Slice B: honest breakdown of non-covered statuses (zero counts omitted).
      var _covParts = [];
      [['stale', agg.research.stale], ['unavailable', agg.research.unavailable],
       ['missing', agg.research.missing], ['unsupported', agg.research.unsupported]].forEach(function(p) {
        if (p[1] > 0) _covParts.push(p[1] + ' ' + p[0]);
      });
      if (_covParts.length > 0) {
        var resDetail = document.createElement('div');
        resDetail.className = 'pf-cov-detail';
        resDetail.textContent = _covParts.join(' · ');
        resStat.appendChild(resDetail);
      }
      covRow.appendChild(resStat);
    }
    if (agg.livePrice !== null) {
      covRow.appendChild(_mkCovStat('Live Price Coverage', agg.livePrice.covered, agg.livePrice.total));
    }
    panel.appendChild(covRow);

    // ─── Slice 1D-1: Passive Data Guidance ────────────────────────────────────
    var guidanceText = null;
    if (agg.manualPl.covered < agg.manualPl.total) {
      var missing = agg.manualPl.total - agg.manualPl.covered;
      guidanceText = 'Manual P/L not entered for ' + missing + ' holding' + (missing === 1 ? '' : 's');
    } else if (agg.research !== null && agg.research.covered < agg.research.total) {
      var rMissing = agg.research.total - agg.research.covered;
      guidanceText = 'Research data missing for ' + rMissing + ' holding' + (rMissing === 1 ? '' : 's');
    } else if (agg.livePrice !== null && agg.livePrice.covered < agg.livePrice.total) {
      var lMissing = agg.livePrice.total - agg.livePrice.covered;
      guidanceText = 'Live prices not loaded for ' + lMissing + ' holding' + (lMissing === 1 ? '' : 's');
    }
    if (guidanceText !== null) {
      var guidance = document.createElement('div');
      guidance.className   = 'pf-guidance';
      guidance.textContent = guidanceText;
      panel.appendChild(guidance);
    }

    // ─── Slice 1D-2: Sort bar ─────────────────────────────────────────────────
    // Recorded value ↓/↑ compares raw positionSize numerically — only
    // meaningful within a single currency. When holdings span more than one
    // of USD / ILS / currency-unknown, those two buttons are disabled
    // rather than silently comparing unlike currencies (no card regrouping
    // — the card list stays flat; see _sortHoldingsEntries's contract
    // comment).
    var _pfCurrencyBucketsPresent = (usdSubtotal > 0 ? 1 : 0) + (ilsSubtotal > 0 ? 1 : 0) + (unknownCurrencyCount > 0 ? 1 : 0);
    var investedSortDisabled = _pfCurrencyBucketsPresent > 1;
    if (investedSortDisabled && _portfolioSortMode !== 'symbol') _portfolioSortMode = 'symbol';

    var sortBar = document.createElement('div');
    sortBar.className = 'pf-sort-bar';
    var sortLbl = document.createElement('span');
    sortLbl.className   = 'pf-sort-lbl';
    sortLbl.textContent = 'Sort';
    sortBar.appendChild(sortLbl);
    [
      { mode: 'symbol',        label: 'Symbol A–Z' },
      { mode: 'invested-desc', label: 'Recorded value ↓' },
      { mode: 'invested-asc',  label: 'Recorded value ↑' }
    ].forEach(function(opt) {
      var isInvestedMode = opt.mode === 'invested-desc' || opt.mode === 'invested-asc';
      var btn = document.createElement('button');
      btn.className   = 'pf-sort-btn' + (_portfolioSortMode === opt.mode ? ' active' : '');
      btn.textContent = opt.label;
      if (isInvestedMode && investedSortDisabled) {
        btn.disabled     = true;
        btn.title        = 'Unavailable — holdings span more than one currency; sorting by recorded value would compare unlike currencies.';
        btn.style.opacity = '0.4';
        btn.style.cursor   = 'not-allowed';
      } else {
        btn.onclick = function() {
          _portfolioSortMode = opt.mode;
          _renderPortfolioPanel();
        };
      }
      sortBar.appendChild(btn);
    });
    panel.appendChild(sortBar);

    // Allocation now always means "share of the full portfolio including
    // cash" (P-2B) — shown ONLY under completeness === true, using
    // reporting.allocationDenominatorValue (the same unified total as
    // Portfolio Total (ILS) above) as denominator. The former single-
    // currency-only fallback (e.g. a valid USD-only-portfolio percentage
    // with no cash/FX involved) is intentionally not used here: presenting
    // a holdings-only percentage under the "allocation" label once cash is
    // part of this feature's model would misrepresent it as the complete
    // portfolio allocation. See Known Assets Total above for what an
    // incomplete portfolio shows instead — allocation has no partial-state
    // equivalent, only shown or suppressed.
    var allocationDenominatorValue = reporting.allocationDenominatorValue;

    var list = document.createElement('div');
    list.className = 'pf-positions-list';
    _sortHoldingsEntries(Object.entries(holdings), _portfolioSortMode).forEach(function(entry) {
      var sym = entry[0];
      var h   = entry[1];
      var card = document.createElement('div');
      card.className = 'pf-pos-card';
      var symEl = document.createElement('div');
      symEl.className   = 'pf-pos-sym';
      symEl.textContent = sym;
      card.appendChild(symEl);

      // _corrupt entries render a minimal, visibly-flagged card — no
      // meta/allocation/P&L/research/live-price, since none of that is
      // meaningful data for an entry that couldn't be read. Edit lets the
      // owner repair it (an explicit replacement, not a silent fix);
      // Delete discards it. Nothing here was silently dropped from storage.
      if (h._corrupt === true) {
        card.style.borderColor = 'var(--red2)';
        var corruptMsg = document.createElement('div');
        corruptMsg.className   = 'pf-pos-meta';
        corruptMsg.style.color = 'var(--red2)';
        corruptMsg.textContent = '⚠ Could not be read — data preserved, not deleted. Edit to repair or Delete to discard.';
        card.appendChild(corruptMsg);
        var corruptActions = document.createElement('div');
        corruptActions.className = 'pf-pos-card-actions';
        var cEditBtn = document.createElement('button');
        cEditBtn.className   = 'btn-pf-edit';
        cEditBtn.textContent = 'Edit';
        cEditBtn.onclick     = function(){ openEditPositionModal(sym); };
        var cDelBtn = document.createElement('button');
        cDelBtn.className   = 'btn-pf-delete';
        cDelBtn.textContent = 'Delete';
        cDelBtn.onclick     = function(){ deletePosition(sym); };
        corruptActions.appendChild(cEditBtn);
        corruptActions.appendChild(cDelBtn);
        card.appendChild(corruptActions);
        list.appendChild(card);
        return;
      }

      var meta = document.createElement('div');
      meta.className = 'pf-pos-meta';
      var _currencyKnown = h.currency === 'USD' || h.currency === 'ILS';
      meta.textContent = _pfFmtCurrencyValue(h.positionSize, h.currency) + ' · Recorded position value' + (_currencyKnown ? '' : ' (currency unknown)');
      card.appendChild(meta);

      var allocEl = document.createElement('div');
      allocEl.className = 'pf-pos-alloc';
      if (completeness && allocationDenominatorValue > 0) {
        var _allocIls = _pfHoldingIlsValue(h, fxCache);
        allocEl.textContent = (_allocIls !== null)
          ? ((_allocIls / allocationDenominatorValue * 100).toFixed(1) + '% of portfolio')
          : '—';
      } else {
        allocEl.textContent = '—';
      }
      card.appendChild(allocEl);

      var plEl = document.createElement('div');
      plEl.className = 'pf-pos-pl';
      if (h.manualPlPct !== undefined && h.manualPlPct !== null) {
        var prefix = h.manualPlPct > 0 ? '+' : '';
        plEl.textContent = 'Baseline manual P/L ' + prefix + Number(h.manualPlPct).toFixed(1) + '%';
        if (h.manualPlPct > 0)      plEl.classList.add('pf-pos-pl--pos');
        else if (h.manualPlPct < 0) plEl.classList.add('pf-pos-pl--neg');
        else                        plEl.classList.add('pf-pos-pl--zero');
      } else {
        plEl.textContent = 'Baseline manual P/L —';
        plEl.classList.add('pf-pos-pl--muted');
      }
      card.appendChild(plEl);

      // ─── P-3: per-holding Unrealized P/L (native + ILS) ────────────────────
      // Pure math lives entirely in _pfHoldingPl; this block only turns its
      // result into DOM, mirroring the plEl block above. Unknown-currency
      // holdings intentionally render NOTHING here (§4: all derived P-3
      // metrics suppressed with no exception) — plEl above already shows
      // the broker-recorded manualPlPct on its own for that case.
      var pl3 = _pfHoldingPl(h, fxCache);
      if (pl3.nativeAvailable) {
        var pl3NativeEl = document.createElement('div');
        pl3NativeEl.className = 'pf-pos-pl';
        var pl3CurrSym = h.currency === 'USD' ? '$' : '₪';
        pl3NativeEl.textContent = 'Unrealized P/L ' + (pl3.plNative >= 0 ? '+' : '-') + pl3CurrSym +
          Math.abs(pl3.plNative).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) +
          ' (' + (pl3.plPctNativePct >= 0 ? '+' : '') + pl3.plPctNativePct.toFixed(2) + '% Native return)';
        if (pl3.plNative > 0)      pl3NativeEl.classList.add('pf-pos-pl--pos');
        else if (pl3.plNative < 0) pl3NativeEl.classList.add('pf-pos-pl--neg');
        else                       pl3NativeEl.classList.add('pf-pos-pl--zero');
        card.appendChild(pl3NativeEl);

        // ILS holdings: native currency IS ILS, so plIls/plPctIlsPct are the
        // exact same numbers as plNative/plPctNativePct above (see
        // _pfHoldingPl's ILS branch — costIls===costBasis, valueIls===
        // positionSize). Rendering a second "Unrealized P/L (ILS)" line for
        // an ILS holding would just duplicate the line above under a
        // different label, not show a genuinely distinct result. Only a USD
        // holding's ILS conversion (costBasisILS + a usable FX rate)
        // produces a number that differs from native, so this whole block
        // — the ILS line and its two suppression messages — is USD-only.
        if (h.currency === 'USD') {
          if (pl3.ilsAvailable) {
            var pl3IlsEl = document.createElement('div');
            pl3IlsEl.className = 'pf-pos-pl';
            pl3IlsEl.textContent = 'Unrealized P/L (ILS) ' + (pl3.plIls >= 0 ? '+' : '-') + '₪' +
              Math.abs(pl3.plIls).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) +
              ' (' + (pl3.plPctIlsPct >= 0 ? '+' : '') + pl3.plPctIlsPct.toFixed(2) + '% Unrealized return (ILS))';
            if (pl3.plIls > 0)      pl3IlsEl.classList.add('pf-pos-pl--pos');
            else if (pl3.plIls < 0) pl3IlsEl.classList.add('pf-pos-pl--neg');
            else                    pl3IlsEl.classList.add('pf-pos-pl--zero');
            card.appendChild(pl3IlsEl);
          } else if (!pl3.costIlsAvailable) {
            var pl3MissingEl = document.createElement('div');
            pl3MissingEl.className   = 'pf-pos-pl pf-pos-pl--muted';
            pl3MissingEl.textContent = 'Unrealized P/L (ILS) — add ILS cost basis';
            card.appendChild(pl3MissingEl);
          } else if (!pl3.fxUsable) {
            var pl3FxEl = document.createElement('div');
            pl3FxEl.className   = 'pf-pos-pl pf-pos-pl--muted';
            pl3FxEl.textContent = 'Unrealized P/L (ILS) — ' + DH_DISPLAY.surface['pl-fx-not-usable'];
            card.appendChild(pl3FxEl);
          }
        }

        if (pl3.driftFlag) {
          var pl3DriftEl = document.createElement('div');
          pl3DriftEl.className   = 'pf-pos-pl';
          pl3DriftEl.style.color = 'var(--yellow2)';
          pl3DriftEl.title       = 'Native return ' + pl3.plPctNativePct.toFixed(2) + '% vs. recorded baseline manual P/L ' + Number(h.manualPlPct).toFixed(2) + '%';
          pl3DriftEl.textContent = '⚠ Drift ' + pl3.driftPp.toFixed(2) + 'pp vs. baseline manual P/L';
          card.appendChild(pl3DriftEl);
        }
        if (pl3.ratioFlag) {
          var pl3RatioEl = document.createElement('div');
          pl3RatioEl.className   = 'pf-pos-pl';
          pl3RatioEl.style.color = 'var(--yellow2)';
          pl3RatioEl.textContent = '⚠ Check units — ILS/native cost ratio ' + pl3.ratio.toFixed(2) + ' outside expected range';
          card.appendChild(pl3RatioEl);
        }
      } else if (h.currency === 'USD' || h.currency === 'ILS') {
        var pl3NoCostEl = document.createElement('div');
        pl3NoCostEl.className   = 'pf-pos-pl pf-pos-pl--muted';
        pl3NoCostEl.textContent = 'Unrealized P/L — add cost basis';
        card.appendChild(pl3NoCostEl);
      }

      // P-2B: the old scan-derived day-change block (48h-freshness, hardcoded
      // $ prefix, read via _getDailyChangeForHolding) was removed here — the
      // P-2A EOD-based estimate below (_updatePortfolioCard's .pf-pos-mkt
      // element) is now the panel's sole day-change source, avoiding two
      // contradictory numbers on one card. With both PT_ENABLE_PORTFOLIO_
      // LIVE_PRICES and PT_ENABLE_PORTFOLIO_FX off, no day-change number is
      // shown here — an accepted, honest consequence, not a regression to
      // silently paper over.
      if (window.PT_ENABLE_PORTFOLIO_LIVE_PRICES === true) {
        var mktEl      = document.createElement('div');
        mktEl.id        = 'pf-mkt-' + sym;
        mktEl.className = 'pf-pos-mkt';
        var mktLoading  = document.createElement('span');
        mktLoading.className   = 'pf-pos-mkt-price';
        mktLoading.textContent = '…';
        mktEl.appendChild(mktLoading);
        card.appendChild(mktEl);
      }
      if (window.PT_ENABLE_PORTFOLIO_RESEARCH === true) {
        // Slice B: classification + provenance via the ResearchView adapter;
        // source selection stays in _resolveResearchForHolding underneath.
        var _view = _researchViewForHolding(sym);
        var res = _view.result;
        var resRow = document.createElement('div');
        resRow.className = 'pf-pos-research';
        if (_view.status === 'unsupported') {
          var resStEl = document.createElement('span');
          resStEl.className = 'pf-res-state unsupported';
          resStEl.textContent = 'Unsupported symbol';
          resRow.appendChild(resStEl);
        } else if (!res) {
          var resStEl = document.createElement('span');
          resStEl.className = 'pf-res-state missing';
          resStEl.textContent = _dhLabel('state', 'missing');
          resRow.appendChild(resStEl);
        } else if (res._aiUnavailable === true) {
          var resStEl = document.createElement('span');
          resStEl.className = 'pf-res-state unavail';
          resStEl.textContent = DH_DISPLAY.surface['ai-unavailable'];
          resRow.appendChild(resStEl);
        } else {
          var isStale = _view.stale;
          var ageMs = _view.ageMs;
          var resStEl = document.createElement('span');
          resStEl.className = 'pf-res-state ' + (isStale ? 'stale' : 'found');
          resStEl.textContent = isStale ? 'Stale' : 'Research';
          resRow.appendChild(resStEl);
          var scEl = document.createElement('span');
          if (typeof res.sentiment_score === 'number') {
            var score = res.sentiment_score;
            var scoreCls = score >= 65 ? 'pos' : score >= 40 ? 'warn' : 'neg';
            scEl.className = 'pf-res-score ' + scoreCls;
            scEl.textContent = 'Score ' + score;
          } else {
            scEl.className = 'pf-res-score';
            scEl.textContent = 'Score —';
          }
          resRow.appendChild(scEl);
          var rM = (res.summary || '').match(RATING_SUMMARY_RE);
          if (rM) {
            var rEl = document.createElement('span');
            rEl.className = 'pf-res-rating neutral-v'; // R-5 (Entry 37): the analyst view is shown neutral; the Pulse view is the score
            rEl.textContent = 'Analyst ' + rM[1].toUpperCase();
            resRow.appendChild(rEl);
          }
          var _setupMap = {healthy_uptrend:['BULLISH','pos'],healthy_uptrend_near_ath:['BULLISH','pos'],pullback_in_uptrend:['MIXED','warn'],support_test:['MIXED','warn'],extended_near_ath:['EXTENDED','warn'],breakdown_risk:['BEARISH','neg'],below_key_mas:['BEARISH','neg']};
          var _setupEntry = _setupMap[res.technical_setup];
          if (_setupEntry) {
            var setupEl = document.createElement('span');
            setupEl.className = 'pf-res-setup ' + _setupEntry[1];
            setupEl.textContent = _setupEntry[0];
            resRow.appendChild(setupEl);
          }
          if (!isStale && (res._catalystDirection === 'bullish' || res._catalystDirection === 'mixed' || res._catalystDirection === 'bearish')) {
            var catEl = document.createElement('span');
            catEl.className = 'pf-res-catalyst ' + (res._catalystDirection === 'bullish' ? 'pos' : res._catalystDirection === 'bearish' ? 'neg' : 'warn');
            catEl.textContent = 'CATALYST ' + res._catalystDirection.toUpperCase();
            resRow.appendChild(catEl);
          }
          if (isStale === false) {
            var _actionAllowlist = {buy:'BUY',hold_wait:'WAIT',avoid:'AVOID'};
            var _actionClsMap = {buy:'buy',hold_wait:'hold-wait',avoid:'avoid'};
            if (res.action && _actionAllowlist[res.action]) {
              var actEl = document.createElement('span');
              actEl.className = 'pf-res-action ' + _actionClsMap[res.action];
              actEl.textContent = _actionAllowlist[res.action];
              resRow.appendChild(actEl);
            }
            var _revAllowlist = {upgrading:'↑ UPGRADING',downgrading:'↓ DOWNGRADING',mixed:'MIXED',stable:'STABLE'};
            var _revClsMap = {upgrading:'up',downgrading:'down',mixed:'mixed',stable:'stable'};
            var _revDir = (res._catalysts && res._catalysts.revisionDir) || null;
            if (_revDir && _revAllowlist[_revDir]) {
              var revEl = document.createElement('span');
              revEl.className = ('pf-res-revision ' + _revClsMap[_revDir]).trim();
              revEl.textContent = _revAllowlist[_revDir];
              resRow.appendChild(revEl);
            }
            var _catActs = (res._catalysts && Array.isArray(res._catalysts.analystActions)) ? res._catalysts.analystActions : [];
            var _firstAct = _catActs.length > 0 ? _catActs[0] : null;
            if (_firstAct && typeof _firstAct.bank === 'string' && _firstAct.bank && typeof _firstAct.target === 'number') {
              var ptEl = document.createElement('span');
              ptEl.className = 'pf-res-analyst';
              ptEl.textContent = String(_firstAct.bank).slice(0, 25) + ' PT $' + _firstAct.target;
              resRow.appendChild(ptEl);
            }
          }
          if (ageMs !== null) {
            var ageEl = document.createElement('span');
            ageEl.className = 'pf-res-age';
            var _ageH = Math.round(ageMs / 3600000);
            ageEl.textContent = _ageH < 1 ? '< 1h ago' : _ageH < 48 ? _ageH + 'h ago' : Math.round(ageMs / 86400000) + 'd ago';
            resRow.appendChild(ageEl);
          }
          if (_view.provenance === 'session' || _view.provenance === 'saved') {
            var provEl = document.createElement('span');
            provEl.className = 'pf-res-provenance';
            provEl.textContent = _view.provenance === "session" ? "· This session’s scan" : "· Saved scan";
            resRow.appendChild(provEl);
          }
        }
        card.appendChild(resRow);
        if (isStale === false) {
          var _krVal = (typeof res.key_risk === 'string') ? res.key_risk.trim() : '';
          if (_krVal && _krVal.toLowerCase() !== 'null') {
            var detRow = document.createElement('div');
            detRow.className = 'pf-res-detail';
            var detLbl = document.createElement('span');
            detLbl.className = 'pf-res-detail-lbl';
            detLbl.textContent = 'Risk:';
            var detVal = document.createElement('span');
            detVal.textContent = _krVal;
            detRow.appendChild(detLbl);
            detRow.appendChild(detVal);
            card.appendChild(detRow);
          }
          (function(_sym, _res, _ageMs) {
            var detailBtn = document.createElement('button');
            detailBtn.className = 'btn-pf-details';
            detailBtn.textContent = 'Details';
            detailBtn.setAttribute('aria-label', 'Open research details for ' + _sym);
            detailBtn.onclick = function() { _openResearchDetailPanel(_sym, _res, _ageMs, detailBtn); };
            card.appendChild(detailBtn);
          })(sym, res, ageMs);
        }
      }
      var cardActions = document.createElement('div');
      cardActions.className = 'pf-pos-card-actions';
      var editBtn = document.createElement('button');
      editBtn.className   = 'btn-pf-edit';
      editBtn.textContent = 'Edit';
      editBtn.onclick     = function(){ openEditPositionModal(sym); };
      var delBtn = document.createElement('button');
      delBtn.className   = 'btn-pf-delete';
      delBtn.textContent = 'Delete';
      delBtn.onclick     = function(){ deletePosition(sym); };
      // P5S5: research trigger — UI wiring only, see _p5RunResearchCard above.
      var p5ResBtn = document.createElement('button');
      p5ResBtn.className   = 'btn-pf-research';
      p5ResBtn.textContent = 'Research';
      p5ResBtn.setAttribute('aria-label', 'Start research for ' + sym);
      p5ResBtn.onclick     = function(){ _p5RunResearchCard(sym); };
      cardActions.appendChild(editBtn);
      cardActions.appendChild(delBtn);
      cardActions.appendChild(p5ResBtn);
      card.appendChild(cardActions);
      var p5Mount = document.createElement('div');
      p5Mount.id = 'pf-p5-mount-' + sym;
      p5Mount.className = 'p5-card-mount';
      card.appendChild(p5Mount);
      list.appendChild(card);
    });
    panel.appendChild(list);
    // Restore any already-displayed P5 packet across a card-list re-render
    // (memory-only; must run after attachment so getElementById can resolve
    // each mount). A run in flight re-renders itself on completion.
    Object.keys(holdings).forEach(function (sym) {
      if (!_p5Pending[sym]) _p5RenderCard(sym);
    });
  }
  if (window.PT_ENABLE_PORTFOLIO_LIVE_PRICES === true && count > 0) {
    var _pfSyms = Object.keys(holdings);
    // P-2A: pure display from the persisted EOD cache — rendering never
    // triggers a fetch, and a terminal condition (e.g. server disabled)
    // never hides previously persisted completed-session data. Terminal
    // state only prevents further fetch attempts (enforced inside
    // _pfEodAutoFetchIfDue/_pfLiveBatch, not here) — it is not surfaced as
    // a banner in this pass.
    var _pfEodCache = _pfEodLoadCache();
    _pfSyms.forEach(function(s) {
      var c = _pfEodCache[s];
      _updatePortfolioCard(s, c ? {
        price: c.price, change_percent: c.changePercent, currency: c.currency,
        sessionEpoch: c.sessionEpoch, stale: _pfEodIsStale(c)
      } : null);
    });
  }
}

_srGroupResults.source:
function _srGroupResults(source) {
  const items = source.slice().sort(_ptScoreCmp); // R-5 (Entry 37, ruling B1): Pulse-only ordering; equal scores keep source order
  // display order: Strong Setup → Watch → Extended / near 1Y high → Caution → Analysis failed — rescan (R-3, Entry 36)
  const groups = [
    { name: 'Strong Setup',   items: [] },
    { name: 'Watch',          items: [] },
    { name: 'Extended / near 1Y high', items: [] },
    { name: 'Caution',        items: [] },
    { name: 'Analysis failed — rescan', items: [] },
  ];
  items.forEach(r => {
    const sc = _ptScoreNorm(r.sentiment_score);
    const ts = r.technical_setup || '';
    if (r._aiUnavailable === true)                groups[4].items.push(r); // R-3 (Entry 36): a failed AI analysis is never ranked by setup
    else if (_SR_BULLISH_TIER.has(ts) && sc !== null && sc >= 55)  groups[0].items.push(r);
    else if (ts === 'extended_near_ath')         groups[2].items.push(r);
    else if (_SR_BEARISH_TIER.has(ts))           groups[3].items.push(r);
    else                                          groups[1].items.push(r);
  });
  return groups;
}

_srRenderGrouped.source:
function _srRenderGrouped(source, tbody) {
  if (!source.length) {
    tbody.innerHTML = '<tr><td colspan="6" class="sr-empty">No scan results yet. Run a scan to see ranked results.</td></tr>';
    return;
  }
  const tfMap = {
    extended_near_ath:        ['EXTENDED', 'warn'],
    healthy_uptrend_near_ath: ['BULLISH',  'pos'],
    healthy_uptrend:          ['BULLISH',  'pos'],
    pullback_in_uptrend:      ['MIXED',    'warn'],
    support_test:             ['MIXED',    'warn'],
    breakdown_risk:           ['BEARISH',  'neg'],
    below_key_mas:            ['BEARISH',  'neg'],
  };
  const groups = _srGroupResults(source);
  const held = _srHeldMap();
  const rows = [];
  groups.forEach(g => {
    if (!g.items.length) return;
    rows.push(`<tr class="sr-group-hdr"><td colspan="6">${_crEsc(g.name)}<span class="sr-group-count">${g.items.length}</span></td></tr>`);
    g.items.forEach(r => {
      const score  = _ptScoreNorm(r.sentiment_score);
      const chg    = typeof r._verifiedChangePct === 'number' ? r._verifiedChangePct : null;
      const chgStr = chg !== null ? (chg >= 0 ? '+' : '') + chg.toFixed(2) + '%' : '—';
      const chgCls = chg === null ? 'neu' : chg > 0 ? 'pos' : chg < 0 ? 'neg' : 'neu';
      const rM     = (r.summary || '').match(RATING_SUMMARY_RE);
      const rating = r.rating || (rM ? rM[1] : null); // R-5 (Entry 37): no "Neutral" fallback
      const rCls   = 'neutral-v'; // R-5 (Entry 37): the analyst rating never colours the review cell
      const [setupLbl, setupCls] = tfMap[r.technical_setup] || ['—', 'neutral-v'];
      const sym  = _crEsc(r.ticker || '');
      const name = _crEsc((r.company_name || '').slice(0, 30));
      rows.push(`<tr data-ticker="${sym}">
        <td class="sr-sym">${sym}${_srHeldHtml(held, r.ticker)}${(() => { const _ks = _nlmConsistencyChecks(r, { price: typeof r._verifiedPrice === 'number' ? r._verifiedPrice : null, held: Object.prototype.hasOwnProperty.call(held, String(r.ticker || '').trim().toUpperCase()) }); return (Array.isArray(_ks) && _ks.length) ? `<span class="sr-warn" title="${_crEsc(_ks.map(k => k.text).join(' · '))}" style="margin-left:6px;font-size:9px;color:var(--yellow2)">⚠ ${_ks.length}</span>` : ''; })()}</td>
        <td class="sr-col-name" style="color:var(--text3);font-size:10px">${name}</td>
        <td class="r sr-score"><span>${_ptScoreText(score)}</span><div class="sr-score-track">${_ptScoreFillHtml(score)}</div></td>
        <td class="sr-rating ${rCls}">${rating ? rating.toUpperCase() : '—'}</td>
        <td class="sr-setup ${setupCls}">${setupLbl}</td>
        <td class="r sr-chg ${chgCls}">${chgStr}</td>
      </tr>`);
    });
  });
  tbody.innerHTML = rows.join('');
}

openScanResultsOverlay.source:
function openScanResultsOverlay() {
  const overlay = document.getElementById('scanResultsOverlay');
  const tbody   = document.getElementById('srRows');
  const countEl = document.getElementById('srCount');
  if (!overlay || !tbody) return;

  // Prefer live in-memory results; fall back to persisted pt_results (read-only)
  const source = (_cockpitResults && _cockpitResults.length)
    ? _cockpitResults
    : _srSafeParseResults();

  const tfMap = {
    extended_near_ath:        ['EXTENDED', 'warn'],
    healthy_uptrend_near_ath: ['BULLISH',  'pos'],
    healthy_uptrend:          ['BULLISH',  'pos'],
    pullback_in_uptrend:      ['MIXED',    'warn'],
    support_test:             ['MIXED',    'warn'],
    breakdown_risk:           ['BEARISH',  'neg'],
    below_key_mas:            ['BEARISH',  'neg'],
  };

  const sorted = source.slice().sort(_ptScoreCmp);

  if (countEl) countEl.textContent = sorted.length + ' ticker' + (sorted.length !== 1 ? 's' : '');

  // Phase 5E: mode buttons, panel class, density — always set for both modes
  const btnR = document.getElementById('srModeRanked');
  const btnD = document.getElementById('srModeReview');
  if (btnR) btnR.classList.toggle('active', _srMode === 'ranked');
  if (btnD) btnD.classList.toggle('active', _srMode === 'review');
  const panel = document.getElementById('srPanel');
  if (panel) { panel.classList.toggle('mode-review', _srMode === 'review'); panel.classList.toggle('compact', _srDensity === 'compact'); }
  const densityBtn = document.getElementById('srDensityBtn');
  if (densityBtn) densityBtn.textContent = _srDensity === 'compact' ? 'Regular' : 'Compact';
  if (_srMode === 'review') { _srRenderGrouped(source, tbody); overlay.style.display = 'flex'; return; }

  if (!sorted.length) {
    tbody.innerHTML = '<tr><td colspan="7" class="sr-empty">No scan results yet. Run a scan to see ranked results.</td></tr>';
  } else {
    const held = _srHeldMap();
    tbody.innerHTML = sorted.map((r, i) => {
      const score  = _ptScoreNorm(r.sentiment_score);
      const chg    = typeof r._verifiedChangePct === 'number' ? r._verifiedChangePct : null;
      const chgStr = chg !== null ? (chg >= 0 ? '+' : '') + chg.toFixed(2) + '%' : '—';
      const chgCls = chg === null ? 'neu' : chg > 0 ? 'pos' : chg < 0 ? 'neg' : 'neu';
      // Use explicit r.rating field if present; fallback to summary regex (same method as renderMainPanel); R-5 (Entry 37): no "Neutral" fallback
      const rM     = (r.summary || '').match(RATING_SUMMARY_RE);
      const rating = r.rating || (rM ? rM[1] : null);
      const rCls   = 'neutral-v'; // R-5 (Entry 37): the analyst rating never colours the ranked cell
      const [setupLbl, setupCls] = tfMap[r.technical_setup] || ['—', 'neutral-v'];
      const sym  = _crEsc(r.ticker || '');
      const name = _crEsc((r.company_name || '').slice(0, 30));
      return `<tr data-ticker="${sym}">
        <td class="r sr-rank">${i + 1}</td>
        <td class="sr-sym">${sym}${_srHeldHtml(held, r.ticker)}${(() => { const _ks = _nlmConsistencyChecks(r, { price: typeof r._verifiedPrice === 'number' ? r._verifiedPrice : null, held: Object.prototype.hasOwnProperty.call(held, String(r.ticker || '').trim().toUpperCase()) }); return (Array.isArray(_ks) && _ks.length) ? `<span class="sr-warn" title="${_crEsc(_ks.map(k => k.text).join(' · '))}" style="margin-left:6px;font-size:9px;color:var(--yellow2)">⚠ ${_ks.length}</span>` : ''; })()}</td>
        <td class="sr-col-name" style="color:var(--text3);font-size:10px">${name}</td>
        <td class="r sr-score">${_vscCellHtml(score)}</td>
        <td class="sr-rating ${rCls}">${rating ? rating.toUpperCase() : '—'}</td>
        <td class="sr-setup ${setupCls}">${setupLbl}</td>
        <td class="r sr-chg ${chgCls}">${chgStr}</td>
      </tr>`;
    }).join('');
  }

  overlay.style.display = 'flex';
}

renderMainPanel.source:
function renderMainPanel(item) {
  const panel = document.getElementById('mainPanel');
  if (!panel) return;

  const score = _ptScoreNorm(item.sentiment_score); // null = missing (never 50, never 0)
  const sent  = item.sentiment==='positive'?'positive':item.sentiment==='negative'?'negative':'neutral';
  let chg   = typeof item._verifiedChangePct==='number' ? item._verifiedChangePct : null;
  let price = item._verifiedPrice ? `$${item._verifiedPrice.toFixed(2)}` : '—';
  const sum   = item.summary || '';
  const sl    = sum.toLowerCase();

  const getS = tag => {
    const m = sum.match(new RegExp(tag+':?\\s*(.+?)(?=KEY EVENT:|ROOT CAUSE:|PRICE CONTEXT:|BULL VS BEAR:|ACTIONABLE TAKE:|Rating:|$)','si'));
    return m ? m[1].trim().replace(/\n/g,' ').replace(/\s+/g,' ') : '';
  };
  const actionable = getS('ACTIONABLE TAKE');
  const keyEvent   = getS('KEY EVENT');

  const rM = sum.match(RATING_SUMMARY_RE);
  const pM = sum.match(/PT:\s*\$?([\d,.]+|consensus unavailable)/i);
  const rating = rM ? rM[1] : null; // R-5 (Entry 37): no silent "Neutral" fallback
  const pt     = pM&&pM[1]!=='consensus unavailable'?'$'+pM[1]:'—';
  const _pulseBand = score === null ? 'neutral-v' : score >= 65 ? 'pos' : score <= 40 ? 'neg' : 'neutral-v'; // R-5 (Entry 37, ruling A1): the Pulse score band colours the dial and the chip

  // Data-quality flag — gates all derived technical/RS/volume metrics
  const hasData    = hasVerifiedMarketData(item);
  const _mktFailed = _mktFailCache[item.ticker] === true; // display-only; never read by scoring

  // Setup grade — removed from header in Phase 2b; kept as dead vars to avoid refactor
  // of lower body panels that may still reference sc/sg (safe: not rendered in header)
  const hasCrit = (item.alerts||[]).some(a=>a.type==='critical');

  // Timeframe Alignment — deterministic map from technical_setup (Phase 6A-3)
  const _tfMap={extended_near_ath:['EXTENDED','warn'],healthy_uptrend_near_ath:['BULLISH','pos'],healthy_uptrend:['BULLISH','pos'],pullback_in_uptrend:['MIXED','warn'],support_test:['MIXED','warn'],breakdown_risk:['BEARISH','neg'],below_key_mas:['BEARISH','neg']};
  const _panelSnap  = _techSnapFor(item.ticker, _techPanelPrice(item)); // Entry 32: one snapshot for distances and Setup
  const _panelSetup = hasData ? classifyTechnicalSetup(_panelSnap) : 'unknown';
  const _fromScan   = hasData && _techPanelPrice(item) !== item._verifiedPrice; // Entry 32: displayed price differs from scan price
  const [phase,phCls]=_panelSetup==='unknown'?['—','neutral-v']:(_tfMap[_panelSetup]||['NEUTRAL','neutral-v']);

  // State values
  const _scoreSt  = _ptScoreStates(score); // missing -> explicit '—' states, never MODERATE / IN LINE
  const riskState = _scoreSt.riskState;
  const riskCls   = _scoreSt.riskCls;
  const cat       = (sl.includes('earnings beat')||sl.includes('upgrade')||sl.includes('hbm')||sl.includes('ai demand'))?'CATALYST PRESENT':
                    (sl.includes('downgrade')||sl.includes('earnings miss'))?'NEGATIVE EVENT':
                    (sl.includes('no verified')||sl.includes('limited catalyst'))?'NO CATALYST':'MONITORING';
  const catCls    = cat==='CATALYST PRESENT'?'pos':cat==='NEGATIVE EVENT'?'neg':cat==='NO CATALYST'?'warn':'neutral-v';
  const volChar   = sl.includes('elevated volume')||sl.includes('high volume')?'ACCUMULATION':sl.includes('light volume')?'DISTRIBUTION':'NEUTRAL';
  const volCls    = volChar==='ACCUMULATION'?'pos':volChar==='DISTRIBUTION'?'neg':'neutral-v';
  const volReg    = Math.abs(chg||0)>4?'ELEVATED':Math.abs(chg||0)>1.5?'NORMAL':'LOW';
  const chgStr    = chg!==null?(chg>=0?'+':'')+chg.toFixed(2)+'%':'—';
  const chgCls    = chg===null?'':chg>0?'pos':chg<0?'neg':'';

  // Watchlist metadata — must be declared before refreshTechPanel call
  const wlEntry   = findTicker(item.ticker);
  const dispName  = ((wlEntry && wlEntry.name) || item.company_name || '').trim();
  const dispExch  = (wlEntry && wlEntry.exchange)  || '';
  const dispSect  = (wlEntry && wlEntry.sector)    || '';
  const dispEtf   = (wlEntry && wlEntry.sectorEtf) || '';
  const metaParts = [dispExch, dispSect].filter(Boolean);
  if (dispEtf) metaParts.push('Benchmark: ' + dispEtf);
  const metaStr   = metaParts.length ? metaParts.join(' · ') : '';

  // Technical snapshot — read from cache (populated async by refreshTechPanel)
  const snap  = _panelSnap;
  const maCls = v => v === 'pos' ? 'pos' : v === 'warn' ? 'warn' : v === 'neg' ? 'neg' : 'neutral-v';

  // Helper: format a pct diff for display
  function fmtPct(val) {
    if (val === null || val === undefined) return '—';
    return (val >= 0 ? '+' : '') + val.toFixed(2) + '%';
  }

  // 7A-2: Position Context helpers — render-only, no scoring/action impact
  function fmtMoney(v) { return '$' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function fmtPnl(v)   { return (v >= 0 ? '+' : '') + v.toFixed(2) + '%'; }
  function derivePositionMode(p) {
    if (!p || p.hasPosition !== true) return { key:'fresh',      label:'Fresh entry',                         cls:'mode-fresh',      valCls:'muted' };
    if (p.pnlPercent === null || p.pnlPercent === undefined)
                                       return { key:'unknown',    label:'Position open / P/L not entered',     cls:'mode-unknown',    valCls:'muted' };
    const v = p.pnlPercent;
    if (v >=  25)                      return { key:'big-winner', label:'Big winner / Protect gains',          cls:'mode-big-winner', valCls:'pos'  };
    if (v >=   5)                      return { key:'profitable', label:'Profitable / Hold core',              cls:'mode-profitable', valCls:'pos'  };
    if (v  >  -5)                      return { key:'flat',       label:'Flat / Decision zone',                cls:'mode-flat',       valCls:'warn' };
                                       return { key:'loss',       label:'Losing position / Risk control',      cls:'mode-loss',       valCls:'neg'  };
  }
  const _pos  = wlEntry && wlEntry.position;
  const _mode = derivePositionMode(_pos);
  const _posCardHtml = (_pos && _pos.hasPosition === true)
    ? `<div class="mp-pos ${_mode.cls}">
         <div class="mp-pos-label">POSITION CONTEXT</div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Holding</span><span class="mp-pos-val">Yes</span></div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Position value</span><span class="mp-pos-val">${_pos.positionValue !== null ? fmtMoney(_pos.positionValue) : 'Not entered'}</span></div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Current P/L</span><span class="mp-pos-val ${_mode.valCls}">${_pos.pnlPercent !== null ? fmtPnl(_pos.pnlPercent) : 'Not entered'}</span></div>
         <div class="mp-pos-row"><span class="mp-pos-lbl">Mode</span><span class="mp-pos-val ${_mode.valCls}">${_mode.label}</span></div>
       </div>`
    : `<div class="mp-pos ${_mode.cls}">
         <div class="mp-pos-label">POSITION CONTEXT</div>
         <div class="mp-pos-muted">No position — fresh-entry framing applies</div>
       </div>`;

  // 7A-3: Position-aware framing — render-only, local-only, never sent to AI/API.
  // Mirrors Position Context mode color so the two cards read as a single section.
  function derivePositionTake(p, technical_setup, mode) {
    if (!mode || mode.key === 'fresh') return null;
    if (mode.key === 'unknown') return 'Position open / P/L not entered — fill in current P/L for tailored framing.';
    const pnl = fmtPnl(p.pnlPercent);
    const ts  = technical_setup || '';
    const ppt = p.partialProfitTaken === true;
    if (mode.key === 'big-winner') {
      const opener = `Existing big winner, ${pnl} unrealized gain.`;
      if (ppt) return opener + ' Runner already established — hold the runner and avoid re-adding while extended.';
      if (ts === 'extended_near_ath') return opener + ' Prioritize profit protection: hold core, consider trimming partial profits into strength, keep a runner, and avoid adding unless price consolidates or reclaims with controlled risk.';
      if (ts === 'pullback_in_uptrend') return opener + ' Pullback inside uptrend — hold core; add only if size allows and a reclaim confirms on rising relative strength.';
      if (ts === 'below_key_mas' || ts === 'breakdown_risk') return opener + ' Trend is weakening — lock in partial profits, tighten stops, and avoid adding.';
      return opener + ' Prioritize profit protection: hold core, consider partial trim into strength, and avoid adding without a controlled setup.';
    }
    if (mode.key === 'profitable') {
      const opener = `Profitable position, ${pnl} unrealized gain.`;
      if (ts === 'extended_near_ath') return opener + ' Hold core; resist adding while extended. Let trend work; consider partial trim if extension grows.';
      if (ts === 'pullback_in_uptrend') return opener + ' Hold core; add only on confirmed reclaim with risk defined.';
      if (ts === 'below_key_mas' || ts === 'breakdown_risk') return opener + ' Trend deteriorating — reduce on bounces or tighten stops.';
      return opener + ' Hold core, let the trend work, and add only on a valid setup.';
    }
    if (mode.key === 'flat') {
